file.content:
== src/main/resources/db/migration/V1__sheet.sql
-- A sheet's own settings. A sheet with no row here has never been changed: its today is the real date.
CREATE TABLE sheet (
    id    VARCHAR(255) PRIMARY KEY,
    today DATE NOT NULL
);
== src/main/resources/db/migration/V2__person.sql
-- The people on a sheet, listed in the order they were added (by id).
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(255) NOT NULL,
    name     VARCHAR(255) NOT NULL,
    grade    VARCHAR(1)   NOT NULL
);
CREATE INDEX person_sheet ON person (sheet_id, id);
== src/main/resources/db/migration/V3__person_name_unique.sql
-- A person's name is unique on its sheet, without regard to case. Names are stored trimmed.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(255) GENERATED ALWAYS AS (LOWER(name));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
== src/main/resources/db/migration/V4__claim.sql
-- A person's claims: an amount (0.00 or more, two decimals), a date and a note (may be empty).
-- Listed newest first (by id).
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(255)   NOT NULL,
    person_id  BIGINT         NOT NULL,
    amount     DECIMAL(19, 2) NOT NULL,
    claim_date DATE           NOT NULL,
    note       VARCHAR(4000)  NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, person_id, id);
== src/main/resources/db/migration/V5__rate.sql
-- The sheet's rate for each grade: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    sheet_id VARCHAR(255)   NOT NULL,
    grade    VARCHAR(1)     NOT NULL,
    pct      DECIMAL(19, 2) NOT NULL,
    PRIMARY KEY (sheet_id, grade)
);
== src/main/resources/db/migration/V6__claim_status.sql
-- A claim's status: DRAFT -> OPEN -> SETTLED, and DRAFT or OPEN -> VOID. Only OPEN and SETTLED
-- claims count toward the totals.
ALTER TABLE claim ADD COLUMN status VARCHAR(16) DEFAULT 'DRAFT' NOT NULL;
== src/main/resources/db/migration/V7__claim_number.sql
-- A claim's number: given when it is opened, the next on its sheet (1, 2, ...), never reused.
-- A draft has none, and voiding a claim clears it.
ALTER TABLE claim ADD COLUMN number BIGINT;
-- The last number given on each sheet. Its row is locked while a number is taken, so two claims
-- opened at once get different numbers.
CREATE TABLE claim_number (
    sheet_id    VARCHAR(255) PRIMARY KEY,
    last_number BIGINT NOT NULL
);
== src/main/resources/db/migration/V8__claim_settled_due.sql
-- A settled claim's due: amount x its person's grade rate at the moment it was settled, kept as it
-- was so later rate changes do not alter it. Null for a claim not settled, or settled while its
-- grade had no rate (its due then stays live).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(19, 2);
== src/main/resources/db/migration/V9__rate_from.sql
-- A rate applies from its from-date: a grade may have several. A rate with no from-date applies from
-- the beginning of time, kept as 0001-01-01 so it can be part of the key. Setting a rate for a grade
-- and from-date that already exist replaces it.
ALTER TABLE rate ADD COLUMN from_date DATE DEFAULT DATE '0001-01-01' NOT NULL;
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD PRIMARY KEY (sheet_id, grade, from_date);
== src/main/resources/db/migration/V10__claim_opened_by.sql
-- The user who opened a claim (moved it from DRAFT to OPEN); null until it is opened. That user
-- may not settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(255);
== src/main/resources/db/migration/V11__person_version.sql
-- Each stored edit of a person moves its version on, so an editor opened on an older version is refused.
ALTER TABLE person ADD COLUMN version BIGINT NOT NULL DEFAULT 0;
== src/main/resources/db/migration/V12__statement.sql
-- A person's statements: each records their due-total at that moment (null when it was n/a), how
-- many of their claims counted then, and the sheet's today when it was taken. Listed by id.
CREATE TABLE statement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(255)   NOT NULL,
    person_id BIGINT         NOT NULL,
    taken_on  DATE           NOT NULL,
    due_total DECIMAL(19, 2),
    claims    INT            NOT NULL,
    taken_by  VARCHAR(255)
);
CREATE INDEX statement_person ON statement (sheet_id, person_id, id);
-- A claim bound by its person's last statement: it shows and totals stated_due (the figure it had
-- then; null when it had none, n/a) until their next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(19, 2);
== src/main/resources/db/migration/V13__period.sql
-- The sheet's periods: each named (unique on the sheet, ignoring case) and spanning from_date to
-- to_date inclusive; no two periods on a sheet overlap. Listed by from-date.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(255) NOT NULL,
    name      VARCHAR(255) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL
);
CREATE INDEX period_sheet ON period (sheet_id, from_date);
== src/main/resources/db/migration/V14__period_closed.sql
-- A closed period: its due-total is fixed at closed_total (the figures of the claims that counted in
-- it when it was closed, skipping n/a); no claim dated inside it may be added, edited or moved on.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(19, 2);
== src/main/resources/db/migration/V15__claim_void_keeps_number.sql
-- A voided claim now keeps the number it was given when opened (still never reused). Claims voided
-- before this change had theirs cleared and stay without one.
COMMENT ON COLUMN claim.number IS 'Given when opened, the next on its sheet; kept when voided, never reused';
== src/main/resources/db/migration/V16__person_retired.sql
-- A person retired from a date: no claim dated after it may be added (null while not retired). A
-- person with a date set counts as retired at once, whatever the date.
ALTER TABLE person ADD COLUMN retired_from DATE;
== src/main/resources/db/migration/V17__person_held.sql
-- A person on hold: while held, their OPEN claims count in no live total; their SETTLED ones still do.
ALTER TABLE person ADD COLUMN held BOOLEAN DEFAULT FALSE NOT NULL;
== src/main/resources/db/migration/V18__role_setting.sql
-- The roles the sheet assigns: a user name with no row here is a clerk.
CREATE TABLE sheet_role (
    sheet_id  VARCHAR(255) NOT NULL,
    user_name VARCHAR(255) NOT NULL,
    role      VARCHAR(32)  NOT NULL,
    PRIMARY KEY (sheet_id, user_name)
);
-- The sheet's settings, by key; a null value is blank (for clerk-limit: no limit). A key with no
-- row here has never been set.
CREATE TABLE sheet_setting (
    sheet_id    VARCHAR(255) NOT NULL,
    setting_key VARCHAR(64)  NOT NULL,
    setting_value VARCHAR(255),
    PRIMARY KEY (sheet_id, setting_key)
);
== src/main/resources/db/migration/V19__patron.sql
-- A person's patrons: other people on the same sheet they named, each at most once.
CREATE TABLE patron (
    sheet_id  VARCHAR(255) NOT NULL,
    person_id BIGINT       NOT NULL,
    patron_id BIGINT       NOT NULL,
    PRIMARY KEY (sheet_id, person_id, patron_id)
);
== src/main/resources/db/migration/V20__person_grade.sql
-- A person's grade is dated: each applies from its from-date until the next. The first grade a
-- person was given applies from the beginning of time, kept as 0001-01-01. Recording a grade for a
-- from-date that already has one replaces it.
CREATE TABLE person_grade (
    sheet_id  VARCHAR(255) NOT NULL,
    person_id BIGINT       NOT NULL,
    from_date DATE         NOT NULL,
    grade     VARCHAR(1)   NOT NULL,
    PRIMARY KEY (person_id, from_date)
);
CREATE INDEX person_grade_sheet ON person_grade (sheet_id, person_id);
INSERT INTO person_grade (sheet_id, person_id, from_date, grade)
    SELECT sheet_id, id, DATE '0001-01-01', grade FROM person;
ALTER TABLE person DROP COLUMN grade;
== src/main/resources/db/migration/V21__claim_corrects.sql
-- A correction (a claim with a negative amount) names, by number, the settled claim of the same
-- person it corrects; null for any other claim.
ALTER TABLE claim ADD COLUMN corrects BIGINT;
== src/main/resources/db/migration/V22__period_numbering.sql
-- A claim's number is now text: the sheet-wide 1, 2, ... as before, or, while the sheet numbers by
-- period, <period name>-<n> (X-<n> for a claim in no period). A correction names it the same way.
ALTER TABLE claim ALTER COLUMN number VARCHAR(255);
ALTER TABLE claim ALTER COLUMN corrects VARCHAR(255);
-- The last number given in each per-period sequence on a sheet ('P:<period name>', or 'X' for claims
-- in no period). Locked while a number is taken, as claim_number is.
CREATE TABLE claim_period_number (
    sheet_id    VARCHAR(255) NOT NULL,
    sequence    VARCHAR(255) NOT NULL,
    last_number BIGINT NOT NULL,
    PRIMARY KEY (sheet_id, sequence)
);
== src/main/resources/db/migration/V23__claim_listed.sql
-- Where a claim is listed among its person's claims, newest first: taken when it is added, and taken
-- anew when it is moved to another person, so it is listed as their newest claim whatever its date.
CREATE SEQUENCE claim_listed_seq;
ALTER TABLE claim ADD COLUMN listed BIGINT DEFAULT NEXT VALUE FOR claim_listed_seq NOT NULL;
CREATE INDEX claim_sheet_listed ON claim (sheet_id, listed);
== src/main/resources/db/migration/V24__claim_due_by.sql
-- A claim's due-by is fixed when it is added: its date plus the terms of its person's grade in force on
-- that date (else the sheet's terms). Claims already kept take their date plus the sheet's terms now.
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim c SET due_by = DATEADD('DAY', COALESCE((SELECT CAST(s.setting_value AS INT) FROM sheet_setting s
    WHERE s.sheet_id = c.sheet_id AND s.setting_key = 'terms'), 14), c.claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
== src/main/resources/db/migration/V25__claim_log.sql
-- A claim's status log: one entry per status it has had, oldest first (by id), each with the user who
-- made the change, the sheet's today then, and the claim's due as computed at that moment (n/a when
-- no rate applied). Claims already kept have no entries.
CREATE TABLE claim_log (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(255) NOT NULL,
    claim_id   BIGINT       NOT NULL,
    status     VARCHAR(16)  NOT NULL,
    by_user    VARCHAR(255) NOT NULL,
    log_date   DATE         NOT NULL,
    due        VARCHAR(32)  NOT NULL
);
CREATE INDEX claim_log_sheet ON claim_log (sheet_id, claim_id, id);
== src/main/resources/db/migration/V26__person_hold.sql
-- A person's holds: each from its from-date to its to-date (null: no end), both inclusive. A person
-- may have several over time. Only their OPEN (or PENDING) claims dated within a hold, and not bound
-- by a statement, are left out of the live totals. A person held before holds were dated is held
-- from the beginning of time (0001-01-01) with no end.
CREATE TABLE person_hold (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(255) NOT NULL,
    person_id BIGINT       NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE
);
CREATE INDEX person_hold_sheet ON person_hold (sheet_id, person_id);
INSERT INTO person_hold (sheet_id, person_id, from_date, to_date)
    SELECT sheet_id, id, DATE '0001-01-01', NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
== src/main/resources/db/migration/V27__rate_to.sql
-- A rate may apply through a to-date (inclusive); null when it has no end. A date after it, with no
-- later rate of the grade in force, has no rate.
ALTER TABLE rate ADD COLUMN to_date DATE;
-- A claim a statement bound while the rate that would apply to it had ended keeps n/a.
ALTER TABLE claim ADD COLUMN stated_na BOOLEAN DEFAULT FALSE NOT NULL;
== src/main/resources/db/migration/V28__period_person_total.sql
-- Each person's due-total in a closed period, fixed when the period was closed (the figures of their
-- claims that counted in it, skipping n/a). The period's closed_total is the sum of these. Dropped on
-- reopening; a person with no row here shows 0.00 for the closed period.
CREATE TABLE period_person_total (
    sheet_id    VARCHAR(255)   NOT NULL,
    period_name VARCHAR(255)   NOT NULL,
    person_id   BIGINT         NOT NULL,
    total       DECIMAL(19, 2) NOT NULL,
    PRIMARY KEY (sheet_id, period_name, person_id)
);
== src/main/resources/db/migration/V29__setting_from.sql
-- The settings that carry a figure are dated: each value is recorded from a from-date, and the value in
-- force on a date is the one with the latest from-date on or before it (before every from-date, the
-- sheet's starting value). A null value is blank (for clerk-limit and cap: none; for a grade's terms:
-- the sheet's). The policy date and the period numbering date stay undated in sheet_setting.
CREATE TABLE sheet_setting_from (
    sheet_id      VARCHAR(255) NOT NULL,
    setting_key   VARCHAR(64)  NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(255),
    PRIMARY KEY (sheet_id, setting_key, from_date)
);
-- A value set before settings were dated holds from the start.
INSERT INTO sheet_setting_from (sheet_id, setting_key, from_date, setting_value)
    SELECT sheet_id, setting_key, DATE '0001-01-01', setting_value FROM sheet_setting
    WHERE setting_key NOT IN ('policy-date', 'period-numbering-from');
DELETE FROM sheet_setting WHERE setting_key NOT IN ('policy-date', 'period-numbering-from');
== src/main/resources/db/migration/V30__claim_deferred.sql
-- An OPEN claim deferred until a date after the sheet's today: until that day it counts in no total,
-- is not overdue, cannot be settled and is left unbound by a statement. Null when never deferred.
ALTER TABLE claim ADD COLUMN deferred_until DATE;
== src/main/resources/db/migration/V31__claim_proofs.sql
-- How many proofs a claim has: raised by one at a time while it is DRAFT, OPEN or PENDING. A claim whose
-- due is above the sheet's proof threshold on its date cannot be settled or approved while it has none.
ALTER TABLE claim ADD COLUMN proofs INT DEFAULT 0 NOT NULL;
== src/main/resources/db/migration/V32__claim_split_from.sql
-- The number of the claim a claim was split off: set when an OPEN claim is split, on the new claim only.
ALTER TABLE claim ADD COLUMN split_from VARCHAR(255);
== src/main/resources/db/migration/V33__watch.sql
-- Who watches whom: a user watching a person on the sheet, each at most once. The id orders a person's
-- watchers by when they started watching; watching again after stopping starts afresh.
CREATE TABLE watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(255) NOT NULL,
    person_id BIGINT       NOT NULL,
    username  VARCHAR(255) NOT NULL,
    UNIQUE (sheet_id, person_id, username)
);
== src/main/resources/db/migration/V34__delegation.sql
-- The steward role delegated to a user by a steward for from..to (inclusive), by the sheet's today.
-- The id orders a sheet's delegations as they were made.
CREATE TABLE delegation (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id    VARCHAR(255) NOT NULL,
    user_name   VARCHAR(255) NOT NULL,
    from_date   DATE         NOT NULL,
    to_date     DATE         NOT NULL,
    delegated_by VARCHAR(255) NOT NULL
);
== src/main/resources/db/migration/V35__sheet_archived.sql
-- An archived sheet stays visible but refuses every change. Only a steward archives a sheet.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN DEFAULT FALSE NOT NULL;
== src/main/resources/db/migration/V36__person_terms.sql
-- A person's own terms: the whole days after its date a claim of theirs is due by, ahead of their
-- grade's and the sheet's terms. Null when they have none.
ALTER TABLE person ADD COLUMN terms INT;
== src/main/resources/db/migration/V37__claim_lock.sql
-- The user whose open editor locks the claim for every other user, until they save or cancel it or
-- the sheet's today changes. Null when it is not locked.
ALTER TABLE claim ADD COLUMN locked_by VARCHAR(255);
== src/main/resources/db/migration/V38__period_soft_close.sql
-- A soft-closed period: its due-total (closed_total) and each person's due-total in it
-- (period_person_total) are fixed as when it was soft-closed, but claims dated inside it may still be
-- added, edited and moved on. It is not closed; closing it fixes the figures afresh, reopening drops them.
ALTER TABLE period ADD COLUMN soft BOOLEAN DEFAULT FALSE NOT NULL;
-- A claim added while the period its date falls in was soft-closed.
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
== src/main/resources/db/migration/V39__history.sql
-- Every version of the rows a person's figures follow, so a statement can be taken as of a past date:
-- each insert, update or delete of a claim, person, grade, hold, rate or setting is kept in <table>_hist
-- (by the trigger net.officefloor.hq.app.history.HistoryTrigger) with the sheet's today when it was made
-- (hist_made_on), in the order made (hist_seq); a deleted row is kept with hist_gone. A row as it stood at
-- the end of a date is its last version made while the sheet's today was on or before that date.
-- A column later added to one of these tables must be added to its _hist table too.
CREATE SEQUENCE hist_seq;

CREATE TABLE claim_hist AS SELECT * FROM claim WITH NO DATA;
CREATE TABLE person_hist AS SELECT * FROM person WITH NO DATA;
CREATE TABLE person_grade_hist AS SELECT * FROM person_grade WITH NO DATA;
CREATE TABLE person_hold_hist AS SELECT * FROM person_hold WITH NO DATA;
CREATE TABLE rate_hist AS SELECT * FROM rate WITH NO DATA;
CREATE TABLE sheet_setting_hist AS SELECT * FROM sheet_setting WITH NO DATA;
CREATE TABLE sheet_setting_from_hist AS SELECT * FROM sheet_setting_from WITH NO DATA;

ALTER TABLE claim_hist ADD COLUMN hist_seq BIGINT NOT NULL;
ALTER TABLE claim_hist ADD COLUMN hist_made_on DATE NOT NULL;
ALTER TABLE claim_hist ADD COLUMN hist_gone BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE person_hist ADD COLUMN hist_seq BIGINT NOT NULL;
ALTER TABLE person_hist ADD COLUMN hist_made_on DATE NOT NULL;
ALTER TABLE person_hist ADD COLUMN hist_gone BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE person_grade_hist ADD COLUMN hist_seq BIGINT NOT NULL;
ALTER TABLE person_grade_hist ADD COLUMN hist_made_on DATE NOT NULL;
ALTER TABLE person_grade_hist ADD COLUMN hist_gone BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE person_hold_hist ADD COLUMN hist_seq BIGINT NOT NULL;
ALTER TABLE person_hold_hist ADD COLUMN hist_made_on DATE NOT NULL;
ALTER TABLE person_hold_hist ADD COLUMN hist_gone BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE rate_hist ADD COLUMN hist_seq BIGINT NOT NULL;
ALTER TABLE rate_hist ADD COLUMN hist_made_on DATE NOT NULL;
ALTER TABLE rate_hist ADD COLUMN hist_gone BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE sheet_setting_hist ADD COLUMN hist_seq BIGINT NOT NULL;
ALTER TABLE sheet_setting_hist ADD COLUMN hist_made_on DATE NOT NULL;
ALTER TABLE sheet_setting_hist ADD COLUMN hist_gone BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE sheet_setting_from_hist ADD COLUMN hist_seq BIGINT NOT NULL;
ALTER TABLE sheet_setting_from_hist ADD COLUMN hist_made_on DATE NOT NULL;
ALTER TABLE sheet_setting_from_hist ADD COLUMN hist_gone BOOLEAN DEFAULT FALSE NOT NULL;

CREATE INDEX claim_hist_key ON claim_hist (id, hist_seq);
CREATE INDEX person_hist_key ON person_hist (id, hist_seq);
CREATE INDEX person_grade_hist_key ON person_grade_hist (person_id, from_date, hist_seq);
CREATE INDEX person_hold_hist_key ON person_hold_hist (id, hist_seq);
CREATE INDEX rate_hist_key ON rate_hist (sheet_id, grade, from_date, hist_seq);
CREATE INDEX sheet_setting_hist_key ON sheet_setting_hist (sheet_id, setting_key, hist_seq);
CREATE INDEX sheet_setting_from_hist_key ON sheet_setting_from_hist (sheet_id, setting_key, from_date, hist_seq);

CREATE TRIGGER claim_history AFTER INSERT, UPDATE, DELETE ON claim FOR EACH ROW
    CALL 'net.officefloor.hq.app.history.HistoryTrigger';
CREATE TRIGGER person_history AFTER INSERT, UPDATE, DELETE ON person FOR EACH ROW
    CALL 'net.officefloor.hq.app.history.HistoryTrigger';
CREATE TRIGGER person_grade_history AFTER INSERT, UPDATE, DELETE ON person_grade FOR EACH ROW
    CALL 'net.officefloor.hq.app.history.HistoryTrigger';
CREATE TRIGGER person_hold_history AFTER INSERT, UPDATE, DELETE ON person_hold FOR EACH ROW
    CALL 'net.officefloor.hq.app.history.HistoryTrigger';
CREATE TRIGGER rate_history AFTER INSERT, UPDATE, DELETE ON rate FOR EACH ROW
    CALL 'net.officefloor.hq.app.history.HistoryTrigger';
CREATE TRIGGER sheet_setting_history AFTER INSERT, UPDATE, DELETE ON sheet_setting FOR EACH ROW
    CALL 'net.officefloor.hq.app.history.HistoryTrigger';
CREATE TRIGGER sheet_setting_from_history AFTER INSERT, UPDATE, DELETE ON sheet_setting_from FOR EACH ROW
    CALL 'net.officefloor.hq.app.history.HistoryTrigger';
== src/main/resources/db/migration/V40__as_of_view.sql
-- The as-of view shows every cell as it stood at the end of a date (see V39__history.sql), so the rest
-- of what the screen shows is kept by version too: statements, periods and their fixed figures, patrons,
-- watches, roles and delegations. A sheet records the sheet's today it was archived on.
CREATE TABLE statement_hist AS SELECT * FROM statement WITH NO DATA;
CREATE TABLE period_hist AS SELECT * FROM period WITH NO DATA;
CREATE TABLE period_person_total_hist AS SELECT * FROM period_person_total WITH NO DATA;
CREATE TABLE patron_hist AS SELECT * FROM patron WITH NO DATA;
CREATE TABLE watch_hist AS SELECT * FROM watch WITH NO DATA;
CREATE TABLE sheet_role_hist AS SELECT * FROM sheet_role WITH NO DATA;
CREATE TABLE delegation_hist AS SELECT * FROM delegation WITH NO DATA;

ALTER TABLE statement_hist ADD COLUMN hist_seq BIGINT NOT NULL;
ALTER TABLE statement_hist ADD COLUMN hist_made_on DATE NOT NULL;
ALTER TABLE statement_hist ADD COLUMN hist_gone BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period_hist ADD COLUMN hist_seq BIGINT NOT NULL;
ALTER TABLE period_hist ADD COLUMN hist_made_on DATE NOT NULL;
ALTER TABLE period_hist ADD COLUMN hist_gone BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period_person_total_hist ADD COLUMN hist_seq BIGINT NOT NULL;
ALTER TABLE period_person_total_hist ADD COLUMN hist_made_on DATE NOT NULL;
ALTER TABLE period_person_total_hist ADD COLUMN hist_gone BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE patron_hist ADD COLUMN hist_seq BIGINT NOT NULL;
ALTER TABLE patron_hist ADD COLUMN hist_made_on DATE NOT NULL;
ALTER TABLE patron_hist ADD COLUMN hist_gone BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE watch_hist ADD COLUMN hist_seq BIGINT NOT NULL;
ALTER TABLE watch_hist ADD COLUMN hist_made_on DATE NOT NULL;
ALTER TABLE watch_hist ADD COLUMN hist_gone BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE sheet_role_hist ADD COLUMN hist_seq BIGINT NOT NULL;
ALTER TABLE sheet_role_hist ADD COLUMN hist_made_on DATE NOT NULL;
ALTER TABLE sheet_role_hist ADD COLUMN hist_gone BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE delegation_hist ADD COLUMN hist_seq BIGINT NOT NULL;
ALTER TABLE delegation_hist ADD COLUMN hist_made_on DATE NOT NULL;
ALTER TABLE delegation_hist ADD COLUMN hist_gone BOOLEAN DEFAULT FALSE NOT NULL;

CREATE INDEX statement_hist_key ON statement_hist (id, hist_seq);
CREATE INDEX period_hist_key ON period_hist (id, hist_seq);
CREATE INDEX period_person_total_hist_key ON period_person_total_hist (sheet_id, period_name, person_id, hist_seq);
CREATE INDEX patron_hist_key ON patron_hist (sheet_id, person_id, patron_id, hist_seq);
CREATE INDEX watch_hist_key ON watch_hist (id, hist_seq);
CREATE INDEX sheet_role_hist_key ON sheet_role_hist (sheet_id, user_name, hist_seq);
CREATE INDEX delegation_hist_key ON delegation_hist (id, hist_seq);

CREATE TRIGGER statement_history AFTER INSERT, UPDATE, DELETE ON statement FOR EACH ROW
    CALL 'net.officefloor.hq.app.history.HistoryTrigger';
CREATE TRIGGER period_history AFTER INSERT, UPDATE, DELETE ON period FOR EACH ROW
    CALL 'net.officefloor.hq.app.history.HistoryTrigger';
CREATE TRIGGER period_person_total_history AFTER INSERT, UPDATE, DELETE ON period_person_total FOR EACH ROW
    CALL 'net.officefloor.hq.app.history.HistoryTrigger';
