package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodResponse;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.SheetStore;

/** The number a claim receives when opened. While the sheet's period-numbering-from is set and the
 *  sheet's today is on or after it, the claim is numbered within the period its due-by falls in,
 *  <period name>-<n> counting from 1 in each period, or X-<n> in its own sequence when it falls in
 *  none. Otherwise it takes the sheet's next sheet-wide number (1, 2, ...), which carries on from
 *  where it left off. */
public final class Numbering {

    /** The sequence of claims due by a date in no period. */
    private static final String NO_PERIOD = "X";

    private Numbering() {
    }

    public static String next(String sheetId, LocalDate dueBy, ClaimStore claims, SettingStore settings,
            SheetStore sheets, PeriodStore periods) {
        LocalDate from = settings.periodNumberingFrom(sheetId);
        if (from == null || sheets.today(sheetId).isBefore(from)) {
            return String.valueOf(claims.nextNumber(sheetId));
        }
        PeriodResponse period = periods.on(sheetId, dueBy);
        if (period == null) {
            return NO_PERIOD + "-" + claims.nextNumber(sheetId, NO_PERIOD);
        }
        return period.name() + "-" + claims.nextNumber(sheetId, "P:" + period.name());
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * The per-sheet settings. {@link #today(String)} is the date every date-dependent decision and
 * default in the app uses — never the real clock.
 */
@Repository
public class SheetStore {

    private final JdbcTemplate jdbc;

    public SheetStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's today: as set on the sheet, else the real date. */
    public LocalDate today(String sheetId) {
        List<LocalDate> found = jdbc.query("SELECT today FROM sheet WHERE id = ?",
                (rs, i) -> rs.getObject(1, LocalDate.class), sheetId);
        return found.isEmpty() ? LocalDate.now() : found.get(0);
    }

    public void setToday(String sheetId, LocalDate today) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) VALUES (?, ?)", sheetId, today);
    }

    /** Records that the sheet has been loaded: from then on it exists. */
    public void markLoaded(String sheetId) {
        jdbc.update("MERGE INTO sheet_loaded (id) KEY (id) VALUES (?)", sheetId);
    }

    /** Whether the sheet exists: it has been loaded (or changed). */
    public boolean exists(String sheetId) {
        Integer found = jdbc.queryForObject("SELECT (SELECT COUNT(*) FROM sheet_loaded WHERE id = ?)"
                + " + (SELECT COUNT(*) FROM sheet WHERE id = ?)", Integer.class, sheetId, sheetId);
        return found != null && found > 0;
    }

    /** Whether the sheet is archived: visible, but every change to it is refused. */
    public boolean archived(String sheetId) {
        List<Boolean> found = jdbc.query("SELECT archived FROM sheet WHERE id = ?",
                (rs, i) -> rs.getBoolean(1), sheetId);
        return !found.isEmpty() && found.get(0);
    }

    /** Whether the sheet was archived while its today was on or before the date. */
    public boolean archivedBy(String sheetId, LocalDate date) {
        List<Boolean> found = jdbc.query("SELECT archived AND archived_on <= ? FROM sheet WHERE id = ?",
                (rs, i) -> rs.getBoolean(1), date, sheetId);
        return !found.isEmpty() && found.get(0);
    }

    /** Archives the sheet, keeping its today as it reads now, and recording that today as the day it was archived. */
    public void archive(String sheetId) {
        LocalDate today = today(sheetId);
        jdbc.update("MERGE INTO sheet (id, today, archived, archived_on) KEY (id) VALUES (?, ?, TRUE, ?)", sheetId,
                today, today);
    }

    /** Refuses any change to an archived sheet. */
    public void refuseArchived(String sheetId) throws InvalidSheetException {
        if (archived(sheetId)) {
            throw new InvalidSheetException("The sheet is archived");
        }
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.role.DelegationStore;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** Lines that only report figures: never marked as made for a delegating steward. */
    private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");

    private final Path file;
    private final DelegationStore delegations;
    /** The records held back on this thread while a change that may yet be refused as a whole runs. */
    private final ThreadLocal<List<String>> held = new ThreadLocal<>();

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, DelegationStore delegations) {
        this.file = Path.of(path);
        this.delegations = delegations;
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. A change made by a user while a
     *  delegation of the steward role to them is in force ends with for=<the steward who delegated>. */
    public synchronized void record(String entry) {
        String delegator = delegator(entry);
        if (delegator != null) {
            entry = entry + " for=" + delegator;
        }
        List<String> holding = held.get();
        if (holding != null) {
            holding.add(entry);
            return;
        }
        append(entry);
    }

    /** Holds back the records this thread makes from now on, until {@link #release()} writes them or
     *  {@link #discard()} drops them: a change refused as a whole writes nothing. */
    public void hold() {
        held.set(new ArrayList<>());
    }

    /** Writes the records held back on this thread, in the order they were made, and stops holding. */
    public synchronized void release() {
        List<String> holding = held.get();
        held.remove();
        if (holding != null) {
            for (String entry : holding) {
                append(entry);
            }
        }
    }

    /** Drops the records held back on this thread, and stops holding. */
    public void discard() {
        held.remove();
    }

    private void append(String entry) {
        try {
