332	    /** Adds an OPEN claim split off {@code from}: its date, note and tags, the given number, opened by the user
333	     *  and due by {@code dueBy}, fixed for {@code terms} business days after its date, listed as its person's newest claim. */
334	    public Claim addSplit(Claim from, BigDecimal amount, String number, String openedBy, LocalDate dueBy, int terms) {
335	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
336	        jdbc.update(con -> {
337	            PreparedStatement ps = con.prepareStatement(
338	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, number, opened_by, due_by, split_from, tags, due_terms) "
339	                            + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
340	                    new String[] { "ID" });
341	            ps.setString(1, from.getSheetId());
342	            ps.setLong(2, from.getPersonId());
343	            ps.setBigDecimal(3, amount);
344	            ps.setDate(4, Date.valueOf(from.getDate()));
345	            ps.setString(5, from.getNote());
346	            ps.setString(6, ClaimStatus.OPEN.name());
347	            ps.setString(7, number);
348	            ps.setString(8, openedBy);
349	            ps.setDate(9, Date.valueOf(dueBy));
350	            ps.setString(10, from.getNumber());
351	            ps.setString(11, from.getTags());
352	            ps.setInt(12, terms);
353	            return ps;
354	        }, keys);
355	        Claim added = new Claim(keys.getKey().longValue(), from.getSheetId(), from.getPersonId(), amount, from.getDate(),
356	                from.getNote(), ClaimStatus.OPEN, number, null, openedBy, false, null, null, dueBy);
357	        added.setSplitFrom(from.getNumber());
358	        added.setTags(from.getTags());
359	        return added;
360	    }
