362	    /** Works out again the due-by of every claim on the sheet that is not SETTLED or VOID and is due by
363	     *  {@code from} or later: the business day the terms it was fixed with after its date, skipping weekends
364	     *  and the given holidays (see {@link HolidayStore#businessDaysAfter}). */
365	    public void refixDueBy(String sheetId, LocalDate from, Set<LocalDate> holidays) {
366	        jdbc.query("SELECT id, claim_date, due_by, due_terms FROM claim WHERE sheet_id = ? AND status NOT IN (?, ?) "
367	                + "AND due_by >= ? AND due_terms IS NOT NULL ORDER BY id", rs -> {
368	                    LocalDate dueBy = HolidayStore.businessDaysAfter(holidays, rs.getObject("claim_date", LocalDate.class),
369	                            rs.getInt("due_terms"));
370	                    if (!dueBy.equals(rs.getObject("due_by", LocalDate.class))) {
371	                        jdbc.update("UPDATE claim SET due_by = ? WHERE sheet_id = ? AND id = ?", Date.valueOf(dueBy),
372	                                sheetId, rs.getLong("id"));
373	                    }
374	                }, sheetId, ClaimStatus.SETTLED.name(), ClaimStatus.VOID.name(), Date.valueOf(from));
375	    }
