394	        boolean moved = jdbc.update("UPDATE claim SET person_id = ?, number = ?, stated = FALSE, stated_due = NULL, "
395	                + "stated_na = FALSE, listed = NEXT VALUE FOR claim_listed_seq "
396	                + "WHERE sheet_id = ? AND id = ? AND status IN (?, ?, ?) AND number IS NOT DISTINCT FROM ?",
397	                personId, number, claim.getSheetId(), claim.getId(), ClaimStatus.DRAFT.name(), ClaimStatus.OPEN.name(),
398	                ClaimStatus.PENDING.name(), claim.getNumber()) == 1;
