422	    /** Takes the next bulk settle batch on the sheet: 1, then 2, and so on, locked as {@link #nextNumber(String)} is. */
423	    public long nextBatch(String sheetId) {
424	        try {
425	            jdbc.update("INSERT INTO settle_batch (sheet_id, last_batch) SELECT ?, 0 FROM DUAL "
426	                    + "WHERE NOT EXISTS (SELECT 1 FROM settle_batch WHERE sheet_id = ?)", sheetId, sheetId);
427	        } catch (DataAccessException e) {
428	            // another transaction added the sheet's counter first
429	        }
430	        jdbc.update("UPDATE settle_batch SET last_batch = last_batch + 1 WHERE sheet_id = ?", sheetId);
431	        return jdbc.queryForObject("SELECT last_batch FROM settle_batch WHERE sheet_id = ?", Long.class, sheetId);
432	    }
