434	    /** Takes the next claim number on the sheet: 1, then 2, and so on. The sheet's counter row stays
435	     *  locked until the transaction ends, so a number is never given twice, and is not used up if
436	     *  the transaction rolls back. */
437	    public long nextNumber(String sheetId) {
438	        try {
439	            jdbc.update("INSERT INTO claim_number (sheet_id, last_number) SELECT ?, 0 FROM DUAL "
440	                    + "WHERE NOT EXISTS (SELECT 1 FROM claim_number WHERE sheet_id = ?)", sheetId, sheetId);
441	        } catch (DataAccessException e) {
442	            // another transaction added the sheet's counter first
443	        }
444	        jdbc.update("UPDATE claim_number SET last_number = last_number + 1 WHERE sheet_id = ?", sheetId);
445	        return jdbc.queryForObject("SELECT last_number FROM claim_number WHERE sheet_id = ?", Long.class, sheetId);
446	    }
