449	     *  as {@link #nextNumber(String)} is. */
450	    public long nextNumber(String sheetId, String sequence) {
451	        try {
452	            jdbc.update("INSERT INTO claim_period_number (sheet_id, sequence, last_number) SELECT ?, ?, 0 FROM DUAL "
453	                    + "WHERE NOT EXISTS (SELECT 1 FROM claim_period_number WHERE sheet_id = ? AND sequence = ?)",
454	                    sheetId, sequence, sheetId, sequence);
455	        } catch (DataAccessException e) {
456	            // another transaction added the sequence's counter first
457	        }
458	        jdbc.update("UPDATE claim_period_number SET last_number = last_number + 1 WHERE sheet_id = ? AND sequence = ?",
459	                sheetId, sequence);
460	        return jdbc.queryForObject("SELECT last_number FROM claim_period_number WHERE sheet_id = ? AND sequence = ?",
461	                Long.class, sheetId, sequence);
