464	    /** Moves every claim of {@code fromId} to {@code intoId}, keeping their numbers and dates, each unbound from any
465	     *  statement figure and listed after the claims {@code intoId} has, in the order they were listed. */
466	    public void moveAll(String sheetId, long fromId, long intoId) {
467	        for (Long id : jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY listed",
468	                Long.class, sheetId, fromId)) {
469	            jdbc.update("UPDATE claim SET person_id = ?, stated = FALSE, stated_due = NULL, stated_na = FALSE, "
470	                    + "listed = NEXT VALUE FOR claim_listed_seq WHERE sheet_id = ? AND id = ?", intoId, sheetId, id);
471	        }
472	    }
