474	    /** Adds a copy of the claim to the person on the other sheet under {@code number} (null for none), correcting
475	     *  and split off the numbers given: its amount, date, note, status, frozen settled figure, opener, due-by and
476	     *  the terms it was fixed with, deferral, proofs, late entry, reminder, tags, void reason and editor, with its
477	     *  status log and comments, listed as the person's newest claim. Any figure a statement bound, its reference,
478	     *  lock and bulk settle batch are not carried. The id of the copy. */
479	    public long copyTo(Claim claim, String toSheet, long toPerson, String number, String corrects, String splitFrom) {
480	        Integer terms = jdbc.queryForObject("SELECT due_terms FROM claim WHERE sheet_id = ? AND id = ?", Integer.class,
481	                claim.getSheetId(), claim.getId());
482	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
483	        jdbc.update(con -> {
484	            PreparedStatement ps = con.prepareStatement(
485	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, number, settled_due, opened_by, "
486	                            + "corrects, due_by, due_terms, deferred_until, proofs, split_from, late_entry, reminded_on, tags, "
487	                            + "void_reason, edited_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
488	                    new String[] { "ID" });
489	            ps.setString(1, toSheet);
490	            ps.setLong(2, toPerson);
491	            ps.setBigDecimal(3, claim.getAmount());
492	            ps.setDate(4, Date.valueOf(claim.getDate()));
493	            ps.setString(5, claim.getNote());
494	            ps.setString(6, claim.getStatus().name());
495	            ps.setString(7, number);
496	            ps.setBigDecimal(8, claim.getSettledDue());
497	            ps.setString(9, claim.getOpenedBy());
498	            ps.setString(10, corrects);
499	            ps.setDate(11, Date.valueOf(claim.getDueBy()));
500	            ps.setObject(12, terms, java.sql.Types.INTEGER);
501	            ps.setDate(13, claim.getDeferredUntil() == null ? null : Date.valueOf(claim.getDeferredUntil()));
502	            ps.setInt(14, claim.getProofs());
503	            ps.setString(15, splitFrom);
504	            ps.setBoolean(16, claim.isLateEntry());
505	            ps.setDate(17, claim.getRemindedOn() == null ? null : Date.valueOf(claim.getRemindedOn()));
506	            ps.setString(18, claim.getTags());
507	            ps.setString(19, claim.getVoidReason());
508	            ps.setString(20, claim.getEditedBy());
509	            return ps;
510	        }, keys);
511	        long id = keys.getKey().longValue();
512	        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, log_date, due) "
513	                + "SELECT ?, ?, status, by_user, log_date, due FROM claim_log WHERE sheet_id = ? AND claim_id = ? ORDER BY id",
514	                toSheet, id, claim.getSheetId(), claim.getId());
515	        jdbc.update("INSERT INTO claim_comment (sheet_id, claim_id, by_user, written_on, text) "
516	                + "SELECT ?, ?, by_user, written_on, text FROM claim_comment WHERE sheet_id = ? AND claim_id = ? ORDER BY id",
517	                toSheet, id, claim.getSheetId(), claim.getId());
518	        return id;
519	    }
