521	    /** Drops every claim of the person, with their status logs and comments. */
522	    public void removeAll(String sheetId, long personId) {
523	        String mine = "SELECT id FROM claim WHERE sheet_id = ? AND person_id = ?";
524	        jdbc.update("DELETE FROM claim_log WHERE sheet_id = ? AND claim_id IN (" + mine + ")", sheetId, sheetId, personId);
525	        jdbc.update("DELETE FROM claim_comment WHERE sheet_id = ? AND claim_id IN (" + mine + ")", sheetId, sheetId, personId);
526	        jdbc.update("DELETE FROM claim WHERE sheet_id = ? AND person_id = ?", sheetId, personId);
527	    }
