556	    /** The people's grades on the sheet (only the one person when {@code personId} is given), by person. */
557	    private Map<Long, NavigableMap<LocalDate, String>> grades(String sheetId, Long personId, String table) {
558	        Map<Long, NavigableMap<LocalDate, String>> grades = new HashMap<>();
559	        jdbc.query("SELECT person_id, from_date, grade FROM " + table + " WHERE sheet_id = ?"
560	                + (personId == null ? "" : " AND person_id = " + personId), rs -> {
561	                    grades.computeIfAbsent(rs.getLong("person_id"), k -> new TreeMap<>())
562	                            .put(rs.getObject("from_date", LocalDate.class), rs.getString("grade"));
563	                }, sheetId);
564	        return grades;
565	    }
566	
567	    /** The people's holds on the sheet (only the one person's when {@code personId} is given), by person, oldest first. */
568	    private Map<Long, List<Hold>> holds(String sheetId, Long personId, String table) {
569	        Map<Long, List<Hold>> holds = new HashMap<>();
570	        jdbc.query("SELECT person_id, from_date, to_date FROM " + table + " WHERE sheet_id = ?"
571	                + (personId == null ? "" : " AND person_id = " + personId) + " ORDER BY id", rs -> {
572	                    holds.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(new Hold(
573	                            rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class)));
574	                }, sheetId);
575	        return holds;
576	    }
577	
578	    /** The people's aliases on the sheet (only the one person's when {@code personId} is given), by person,
579	     *  sorted as names are compared. */
580	    private Map<Long, List<String>> aliases(String sheetId, Long personId, String table) {
581	        Map<Long, List<String>> aliases = new HashMap<>();
582	        jdbc.query("SELECT person_id, alias FROM " + table + " WHERE sheet_id = ?"
583	                + (personId == null ? "" : " AND person_id = " + personId) + " ORDER BY LOWER(alias), alias", rs -> {
584	                    aliases.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(rs.getString("alias"));
585	                }, sheetId);
586	        return aliases;
587	    }
588	
589	    /** The people's past retirements on the sheet (only the one person's when {@code personId} is given), by
590	     *  person, oldest first. */
591	    private Map<Long, List<PastRetirement>> pastRetirements(String sheetId, Long personId) {
592	        Map<Long, List<PastRetirement>> past = new HashMap<>();
593	        jdbc.query("SELECT person_id, from_date, to_date FROM person_retirement WHERE sheet_id = ?"
594	                + (personId == null ? "" : " AND person_id = " + personId) + " ORDER BY id", rs -> {
595	                    past.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(new PastRetirement(
596	                            rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class)));
597	                }, sheetId);
598	        return past;
599	    }
