601	    private List<Person> query(String sheetId, Long personId, String sql, Object... args) {
602	        return queryFrom(sheetId, personId, "person_grade", "person_hold", "person_alias", sql, args);
603	    }
604	
605	    private List<Person> queryFrom(String sheetId, Long personId, String gradeTable, String holdTable,
606	            String aliasTable, String sql, Object... args) {
607	        Map<Long, NavigableMap<LocalDate, String>> grades = grades(sheetId, personId, gradeTable);
608	        Map<Long, List<Hold>> holds = holds(sheetId, personId, holdTable);
609	        Map<Long, List<String>> aliases = aliases(sheetId, personId, aliasTable);
610	        Map<Long, List<PastRetirement>> past = pastRetirements(sheetId, personId);
611	        RowMapper<Person> row = (rs, i) -> {
612	            Person p = new Person(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"),
613	                    grades.getOrDefault(rs.getLong("id"), new TreeMap<>()), rs.getLong("version"),
614	                    rs.getObject("retired_from", LocalDate.class), holds.getOrDefault(rs.getLong("id"), List.of()));
615	            p.setTerms(rs.getObject("terms", Integer.class));
616	            p.setContact(rs.getString("contact"));
617	            p.setOrigin(rs.getString("origin"));
618	            p.getAliases().addAll(aliases.getOrDefault(rs.getLong("id"), List.of()));
619	            p.getPastRetirements().addAll(past.getOrDefault(rs.getLong("id"), List.of()));
620	            return p;
621	        };
622	        return jdbc.query(sql, row, args);
623	    }
