632	        return queryFrom(sheetId, null, History.asOf("person_grade", "person_id, from_date", date),
633	                History.asOf("person_hold", "id", date), History.asOf("person_alias", "id", date),
634	                "SELECT * FROM " + History.asOf("person", "id", date) + " WHERE sheet_id = ? ORDER BY list_position, id", sheetId);
