651	    /** The person on the sheet with this name or alias, ignoring case and the spaces around it; null when none. */
652	    public Person findByName(String sheetId, String name) {
653	        List<Person> found = query(sheetId, null, "SELECT * FROM person WHERE sheet_id = ? AND (name_key = LOWER(?)"
654	                + " OR id IN (SELECT person_id FROM person_alias WHERE sheet_id = ? AND alias_key = LOWER(?)))",
655	                sheetId, name.trim(), sheetId, name.trim());
656	        return found.isEmpty() ? null : found.get(0);
657	    }
