659	    /** Whether another person on the sheet (not {@code exceptId}) has this name, or anyone on the sheet has it
660	     *  as an alias, ignoring case. */
661	    public boolean nameTaken(String sheetId, String name, Long exceptId) {
662	        Integer n = jdbc.queryForObject(
663	                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(?) AND id <> ?",
664	                Integer.class, sheetId, name.trim(), exceptId == null ? -1L : exceptId);
665	        return (n != null && n > 0) || aliasTaken(sheetId, name);
666	    }
