668	    /** Whether anyone on any of the sheets has this name or alias, ignoring case and the spaces around it. */
669	    public boolean usedOn(List<String> sheetIds, String name) {
670	        for (String sheetId : sheetIds) {
671	            if (nameTaken(sheetId, name, null)) {
672	                return true;
673	            }
674	        }
675	        return false;
676	    }
