678	    /** The names and aliases used on any of the sheets, lower-cased. */
679	    public java.util.Set<String> namesOn(List<String> sheetIds) {
680	        java.util.Set<String> names = new java.util.HashSet<>();
681	        for (String sheetId : sheetIds) {
682	            names.addAll(jdbc.queryForList("SELECT name_key FROM person WHERE sheet_id = ?", String.class, sheetId));
683	            names.addAll(jdbc.queryForList("SELECT alias_key FROM person_alias WHERE sheet_id = ?", String.class,
684	                    sheetId));
