689	    /** Whether the person's name or any of their aliases is among the names (lower-cased). */
690	    public static boolean clashes(Person person, java.util.Set<String> names) {
691	        if (names.contains(person.getName().trim().toLowerCase(java.util.Locale.ROOT))) {
692	            return true;
693	        }
694	        return person.getAliases().stream().anyMatch(a -> names.contains(a.trim().toLowerCase(java.util.Locale.ROOT)));
