697	    /** Whether anyone on the sheet has this alias, ignoring case and the spaces around it. */
698	    public boolean aliasTaken(String sheetId, String alias) {
699	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM person_alias WHERE sheet_id = ? AND alias_key = LOWER(?)",
700	                Integer.class, sheetId, alias.trim());
