704	    /** Adds the alias (trimmed) to the person's aliases. An edit of their name or grade leaves them as they are. */
705	    public void addAlias(Person person, String alias) {
706	        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) VALUES (?, ?, ?)", person.getSheetId(),
707	                person.getId(), alias.trim());
708	        person.getAliases().add(alias.trim());
709	        person.getAliases().sort(java.util.Comparator.comparing((String a) -> a.toLowerCase(java.util.Locale.ROOT))
710	                .thenComparing(java.util.Comparator.naturalOrder()));
