718	    /** Adds the person with their first grade, which applies from the beginning of time, and their own
719	     *  terms (null for none). */
720	    public Person add(String sheetId, String name, String grade, Integer terms) {
721	        return add(sheetId, name, grade, terms, null);
722	    }
723	
724	    /** Whether another person on the sheet (not {@code exceptId}) has this contact (trimmed, lower-cased). */
725	    public boolean contactTaken(String sheetId, String contact, Long exceptId) {
726	        Integer n = jdbc.queryForObject(
727	                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND contact = ? AND id <> ?",
728	                Integer.class, sheetId, contact, exceptId == null ? -1L : exceptId);
729	        return n != null && n > 0;
