731	
732	    /** Adds the person with their first grade, which applies from the beginning of time, their own
733	     *  terms (null for none) and their contact (null for none). */
734	    public Person add(String sheetId, String name, String grade, Integer terms, String contact) {
735	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
736	        jdbc.update(con -> {
737	            PreparedStatement ps = con.prepareStatement(
738	                    "INSERT INTO person (sheet_id, name, terms, contact, list_position) VALUES (?, ?, ?, ?, (SELECT"
739	                    + " COALESCE(MAX(list_position), 0) + 1 FROM person WHERE sheet_id = ?))", new String[] { "ID" });
740	            ps.setString(1, sheetId);
741	            ps.setString(2, name);
742	            ps.setObject(3, terms, java.sql.Types.INTEGER);
743	            ps.setString(4, contact);
744	            ps.setString(5, sheetId);
745	            return ps;
746	        }, keys);
747	        long id = keys.getKey().longValue();
748	        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, ?, ?)", sheetId,
749	                id, Person.START, grade);
750	        Person person = new Person(id, sheetId, name, new TreeMap<>(Map.of(Person.START, grade)), 0);
751	        person.setTerms(terms);
752	        person.setContact(contact);
753	        return person;
754	    }
755	
756	    /**
757	     * Stores the person over the version it was loaded at, moving the version on; false (nothing
758	     * stored) when someone else has stored another version since. The grade the edit records (if any)
759	     * is kept with the ones already recorded, replacing one from the same date.
760	     */
761	    public boolean save(Person person) {
762	        int n = jdbc.update(
763	                "UPDATE person SET name = ?, terms = ?, contact = ?, version = version + 1 WHERE sheet_id = ? AND id = ? AND version = ?",
764	                person.getName(), person.getTerms(), person.getContact(), person.getSheetId(), person.getId(), person.getVersion());
765	        if (n == 1) {
766	            person.setVersion(person.getVersion() + 1);
767	            LocalDate from = person.getRecordFrom();
768	            if (from != null) {
769	                jdbc.update("MERGE INTO person_grade (sheet_id, person_id, from_date, grade) KEY (person_id, from_date)"
770	                        + " VALUES (?, ?, ?, ?)", person.getSheetId(), person.getId(), from, person.getGrades().get(from));
771	            }
772	        }
773	        return n == 1;
774	    }
775	
776	    /**
777	     * Swaps the person with their neighbour in the list (the one above when {@code up}, else the one below);
778	     * answers the person's new position in the list, counting from 1, or 0 (nothing stored) when there is no
779	     * neighbour that way: the top cannot move up, nor the bottom down. An edit of them leaves it as it is.
780	     */
781	    public int move(Person person, boolean up) {
782	        List<long[]> order = jdbc.query("SELECT id, list_position FROM person WHERE sheet_id = ? ORDER BY list_position, id"
783	                + " FOR UPDATE", (rs, i) -> new long[] { rs.getLong("id"), rs.getLong("list_position") },
784	                person.getSheetId());
785	        int at = -1;
786	        for (int i = 0; i < order.size(); i++) {
787	            if (order.get(i)[0] == person.getId()) {
788	                at = i;
789	            }
790	        }
791	        int to = up ? at - 1 : at + 1;
792	        if (at < 0 || to < 0 || to >= order.size()) {
793	            return 0;
794	        }
795	        long[] mine = order.get(at);
796	        long[] theirs = order.get(to);
797	        if (mine[1] == theirs[1]) {
798	            // tied positions (never made by this store): number them apart first, so the swap moves them
799	            renumber(person.getSheetId(), order);
800	            return move(person, up);
801	        }
802	        jdbc.update("UPDATE person SET list_position = ? WHERE sheet_id = ? AND id = ?", theirs[1], person.getSheetId(),
803	                mine[0]);
804	        jdbc.update("UPDATE person SET list_position = ? WHERE sheet_id = ? AND id = ?", mine[1], person.getSheetId(),
805	                theirs[0]);
806	        return to + 1;
807	    }
808	
809	    /** Gives the people positions 1, 2, ... in their present order. */
810	    private void renumber(String sheetId, List<long[]> order) {
811	        for (int i = 0; i < order.size(); i++) {
812	            jdbc.update("UPDATE person SET list_position = ? WHERE sheet_id = ? AND id = ?", i + 1, sheetId, order.get(i)[0]);
813	        }
814	    }
815	
816	    /** Retires the person from the date. An edit of their name or grade leaves it as it is. */
817	    public void retire(Person person, LocalDate from) {
818	        jdbc.update("UPDATE person SET retired_from = ? WHERE sheet_id = ? AND id = ?", from, person.getSheetId(),
819	                person.getId());
820	        person.setRetiredFrom(from);
821	    }
822	
823	    /** Unretires the person on the date, keeping their retirement as a past one, from its date to this one. */
824	    public void unretire(Person person, LocalDate on) {
825	        jdbc.update("INSERT INTO person_retirement (sheet_id, person_id, from_date, to_date) VALUES (?, ?, ?, ?)",
826	                person.getSheetId(), person.getId(), person.getRetiredFrom(), on);
827	        jdbc.update("UPDATE person SET retired_from = NULL WHERE sheet_id = ? AND id = ?", person.getSheetId(),
828	                person.getId());
829	        person.getPastRetirements().add(new PastRetirement(person.getRetiredFrom(), on));
830	        person.setRetiredFrom(null);
831	    }
832	
833	    /** Adds a hold to the person's holds. An edit of their name or grade leaves them as they are. */
834	    public void hold(Person person, Hold hold) {
835	        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date) VALUES (?, ?, ?, ?)",
836	                person.getSheetId(), person.getId(), hold.from(), hold.to());
837	        person.addHold(hold);
838	    }
839	
840	    /** Adds a copy of the person to the other sheet: their name, every grade with its from-date, their terms,
841	     *  contact and aliases, noting this sheet as the one they came from. Their holds, statements and watchers
842	     *  are not carried. */
843	    public Person copyTo(Person person, String toSheet) {
844	        Person copy = add(toSheet, person.getName(), person.gradeOn(Person.START), person.getTerms(), person.getContact());
845	        person.getGrades().forEach((from, grade) -> {
846	            if (!from.equals(Person.START)) {
847	                jdbc.update("INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, ?, ?)",
848	                        toSheet, copy.getId(), from, grade);
849	            }
850	        });
851	        for (String alias : person.getAliases()) {
852	            addAlias(copy, alias);
853	        }
854	        jdbc.update("UPDATE person SET origin = ? WHERE sheet_id = ? AND id = ?", person.getSheetId(), toSheet,
855	                copy.getId());
856	        return find(toSheet, copy.getId());
857	    }
858	
859	    /** Drops the person from their sheet with their grades, holds, aliases, statements and watchers. Their claims,
860	     *  patrons and pool memberships are dropped before this (see ClaimStore, PatronStore and PoolStore). */
861	    public void remove(Person person) {
862	        String sheetId = person.getSheetId();
863	        jdbc.update("DELETE FROM person_alias WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
864	        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, person.getId());
865	        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
866	        jdbc.update("DELETE FROM person_hold WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
867	        jdbc.update("DELETE FROM person_retirement WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
868	        jdbc.update("DELETE FROM statement WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
869	        jdbc.update("DELETE FROM watch WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
870	    }
871	
872	    /** Makes the person's name and aliases aliases of {@code into}, then drops the person with their grades,
873	     *  holds, statements and watchers (their contact goes with them). Their claims, patrons and pool
874	     *  memberships are moved before this (see ClaimStore, PatronStore and PoolStore). */
875	    public void mergeInto(Person person, Person into) {
876	        String sheetId = person.getSheetId();
877	        jdbc.update("UPDATE person_alias SET person_id = ? WHERE sheet_id = ? AND person_id = ?", into.getId(), sheetId,
878	                person.getId());
879	        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, person.getId());
880	        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) VALUES (?, ?, ?)", sheetId, into.getId(),
881	                person.getName());
882	        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
883	        jdbc.update("DELETE FROM person_hold WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
884	        jdbc.update("DELETE FROM person_retirement WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
885	        jdbc.update("DELETE FROM statement WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
886	        jdbc.update("DELETE FROM watch WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
887	    }
888	}
