    /** Logs the claim's current status, by the user, on the sheet's today, at its due as the screen
     *  works it out now (its settled due once settled, else its figure plus any late charge). */
    public void record(Claim claim, String user) {
        String sheetId = claim.getSheetId();
        LocalDate today = sheets.today(sheetId);
        Person person = people.find(sheetId, claim.getPersonId());
        BigDecimal pct = person == null ? null
                : rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
        BigDecimal due = Lateness.of(sheetId, settings, sheets, claims, people).due(claim, pct);
        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, log_date, due) VALUES (?, ?, ?, ?, ?, ?)",
                sheetId, claim.getId(), claim.getStatus().name(), user, Date.valueOf(today),
                due == null ? "n/a" : due.setScale(2).toPlainString());
    }

    /** Every claim's log lines on the sheet, by claim id, oldest first. */
    public Map<Long, List<String>> lines(String sheetId) {
        return lines(sheetId, null);
    }

    /** Every claim's log lines on the sheet logged on or before the date (all of them when it is null), by
     *  claim id, oldest first. */
    public Map<Long, List<String>> lines(String sheetId, LocalDate until) {
        Map<Long, List<String>> lines = new HashMap<>();
        jdbc.query("SELECT * FROM claim_log WHERE sheet_id = ? AND (CAST(? AS DATE) IS NULL OR log_date <= ?) ORDER BY id", rs -> {
            lines.computeIfAbsent(rs.getLong("claim_id"), id -> new ArrayList<>())
                    .add(rs.getString("status") + " by " + rs.getString("by_user") + " on "
                            + rs.getObject("log_date", LocalDate.class) + " due=" + rs.getString("due"));
        }, sheetId, until == null ? null : Date.valueOf(until), until == null ? null : Date.valueOf(until));
        return lines;
    }

    /** Each claim's status at the end of the date, by claim id, as its log records it: the last status
     *  logged on or before the date. A claim logged only after it (added after it) is absent. */
    public Map<Long, ClaimStatus> statusesAt(String sheetId, LocalDate date) {
        Map<Long, ClaimStatus> statuses = new HashMap<>();
        jdbc.query("SELECT claim_id, status FROM claim_log WHERE sheet_id = ? AND log_date <= ? ORDER BY id", rs -> {
            statuses.put(rs.getLong("claim_id"), ClaimStatus.valueOf(rs.getString("status")));
        }, sheetId, Date.valueOf(date));
        return statuses;
    }

    /** The sheet's today on which the claim was last logged SETTLED; null when it never was. */
    public LocalDate settledOn(Claim claim) {
        return lastOn(claim, ClaimStatus.SETTLED);
    }

    /** The sheet's today on which the claim was last logged with the status; null when it never was. */
    public LocalDate lastOn(Claim claim, ClaimStatus status) {
        List<LocalDate> dates = jdbc.query("SELECT log_date FROM claim_log WHERE sheet_id = ? AND claim_id = ? "
                + "AND status = ? ORDER BY id DESC LIMIT 1", (rs, n) -> rs.getObject("log_date", LocalDate.class),
                claim.getSheetId(), claim.getId(), status.name());
        return dates.isEmpty() ? null : dates.get(0);
    }

    /** The claim's log lines, oldest first. */
    public List<String> lines(Claim claim) {
        return lines(claim.getSheetId()).getOrDefault(claim.getId(), List.of());
    }

    /** The sheet's today on which each claim was first logged OPEN, by claim id; a claim never opened is absent. */
    public Map<Long, LocalDate> openedOn(String sheetId) {
        Map<Long, LocalDate> opened = new HashMap<>();
        jdbc.query("SELECT claim_id, MIN(log_date) AS opened FROM claim_log WHERE sheet_id = ? AND status = ? GROUP BY claim_id",
                rs -> {
                    opened.put(rs.getLong("claim_id"), rs.getObject("opened", LocalDate.class));
                }, sheetId, ClaimStatus.OPEN.name());
        return opened;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.time.LocalDate;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.holiday.HolidayStore;
import org.springframework.dao.DataAccessException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The claims kept per sheet, newest first: by when each was added, or moved to its person. */
@Repository
public class ClaimStore {

    private static final RowMapper<Claim> ROW = (rs, i) -> {
        Claim claim = new Claim(rs.getLong("id"), rs.getString("sheet_id"),
            rs.getLong("person_id"), rs.getBigDecimal("amount"), rs.getObject("claim_date", LocalDate.class),
            rs.getString("note"), ClaimStatus.valueOf(rs.getString("status")),
            rs.getString("number"), rs.getBigDecimal("settled_due"),
            rs.getString("opened_by"), rs.getBoolean("stated"), rs.getBigDecimal("stated_due"),
            rs.getString("corrects"), rs.getObject("due_by", LocalDate.class));
        claim.setStatedNa(rs.getBoolean("stated_na"));
        claim.setDeferredUntil(rs.getObject("deferred_until", LocalDate.class));
        claim.setProofs(rs.getInt("proofs"));
        claim.setSplitFrom(rs.getString("split_from"));
        claim.setLateEntry(rs.getBoolean("late_entry"));
        claim.setRemindedOn(rs.getObject("reminded_on", LocalDate.class));
        claim.setRef(rs.getString("ref"));
        claim.setTags(rs.getString("tags"));
        claim.setVoidReason(rs.getString("void_reason"));
        claim.setEditedBy(rs.getString("edited_by"));
        claim.setBatch(rs.getObject("settle_batch", Long.class));
        return claim;
    };

    private final JdbcTemplate jdbc;

    public ClaimStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<Claim> list(String sheetId) {
        return jdbc.query("SELECT * FROM claim WHERE sheet_id = ? ORDER BY listed DESC", ROW, sheetId);
    }

    /** The sheet's claims as they stood at the end of the date (see {@link History}), newest first. */
    public List<Claim> listAsOf(String sheetId, LocalDate date) {
        return jdbc.query("SELECT * FROM " + History.asOf("claim", "id", date) + " WHERE sheet_id = ? ORDER BY listed DESC",
                ROW, sheetId);
    }

    public Claim find(String sheetId, long id) {
        List<Claim> found = jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND id = ?", ROW, sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person's claim with the number, or null when they have none. */
    public Claim findByNumber(String sheetId, long personId, String number) {
        List<Claim> found = jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND person_id = ? AND number = ?", ROW,
                sheetId, personId, number);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Every tag ever carried by a claim on the sheet (by its history, see {@link History}), as stored (see
     *  {@link Tags}); up to the end of {@code date} when given, else up to now. */
    public List<String> tagsEverUsed(String sheetId, LocalDate date) {
        return date == null
                ? jdbc.queryForList("SELECT DISTINCT tags FROM claim_hist WHERE sheet_id = ? AND tags IS NOT NULL "
                        + "UNION SELECT DISTINCT tags FROM claim WHERE sheet_id = ? AND tags IS NOT NULL",
                        String.class, sheetId, sheetId)
                : jdbc.queryForList("SELECT DISTINCT tags FROM claim_hist WHERE sheet_id = ? AND tags IS NOT NULL "
                        + "AND hist_made_on <= ?", String.class, sheetId, Date.valueOf(date));
    }

    /** Whether a claim on the sheet other than {@code exceptId} carries the reference, compared without regard to case. */
    public boolean refTaken(String sheetId, String ref, long exceptId) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND LOWER(ref) = LOWER(?) AND id <> ?",
                Integer.class, sheetId, ref, exceptId);
        return n != null && n > 0;
    }

    /** Adds a draft claim due by {@code dueBy}, fixed for {@code terms} business days after its date (see
     *  {@link #refixDueBy}), with the external reference and tags (null for none). */
    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects,
            LocalDate dueBy, int terms, String ref, String tags) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, corrects, due_by, ref, tags, due_terms) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    new String[] { "ID" });
            ps.setString(1, sheetId);
            ps.setLong(2, personId);
            ps.setBigDecimal(3, amount);
            ps.setDate(4, Date.valueOf(date));
            ps.setString(5, note);
            ps.setString(6, corrects);
            ps.setDate(7, Date.valueOf(dueBy));
            ps.setString(8, ref);
            ps.setString(9, tags);
            ps.setInt(10, terms);
            return ps;
        }, keys);
        Claim added = new Claim(keys.getKey().longValue(), sheetId, personId, amount, date, note, ClaimStatus.DRAFT, null, null, null,
                false, null, corrects, dueBy);
        added.setRef(ref);
        added.setTags(tags);
        return added;
    }

    /** Marks the added claim a late entry: added while the period its due-by falls in was soft-closed. */
    public void markLateEntry(Claim claim) {
        jdbc.update("UPDATE claim SET late_entry = TRUE WHERE sheet_id = ? AND id = ?", claim.getSheetId(), claim.getId());
        claim.setLateEntry(true);
    }

    public void save(Claim claim) {
        jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, number = ?, settled_due = ?, opened_by = ?, void_reason = ? "
                + "WHERE sheet_id = ? AND id = ?",
                claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(), claim.getStatus().name(),
                claim.getNumber(), claim.getSettledDue(), claim.getOpenedBy(), claim.getVoidReason(), claim.getSheetId(), claim.getId());
    }

    /** Stores a draft's amount, date, note, the claim it corrects, its reference, its tags and who edited it, releasing its lock; false when the stored claim is no longer a draft. */
    public boolean edit(Claim claim) {
        return jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, corrects = ?, ref = ?, tags = ?, edited_by = ?, locked_by = NULL WHERE sheet_id = ? AND id = ? AND status = ?",
                claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(), claim.getCorrects(), claim.getRef(), claim.getTags(), claim.getEditedBy(), claim.getSheetId(), claim.getId(),
                ClaimStatus.DRAFT.name()) == 1;
    }

    /** Locks the claim for the user opening its editor (again, when they hold it already); false while
     *  another user holds its lock. */
    public boolean lock(Claim claim, String user) {
        return jdbc.update("UPDATE claim SET locked_by = ? WHERE sheet_id = ? AND id = ? AND (locked_by IS NULL OR locked_by = ?)",
                user, claim.getSheetId(), claim.getId(), user) == 1;
    }

    /** Releases the user's lock on the claim; another user's lock stays. */
    public void unlock(Claim claim, String user) {
        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND id = ? AND locked_by = ?",
                claim.getSheetId(), claim.getId(), user);
    }

    /** Whether a user other than this one holds the claim's lock. */
    public boolean lockedByOther(Claim claim, String user) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND id = ? AND locked_by IS NOT NULL AND locked_by <> ?",
                Integer.class, claim.getSheetId(), claim.getId(), user);
        return n != null && n > 0;
    }

    /** Releases every lock on the sheet's claims, as its today changes. */
    public void unlockAll(String sheetId) {
        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND locked_by IS NOT NULL", sheetId);
    }

    /** The person's claims, newest first, their rows locked until the transaction ends. */
    public List<Claim> listForUpdate(String sheetId, long personId) {
        return jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY listed DESC FOR UPDATE",
                ROW, sheetId, personId);
    }

    /** Binds the claim to the figure (null for n/a), or unbinds it when not {@code stated}. */
    public void bind(Claim claim) {
        jdbc.update("UPDATE claim SET stated = ?, stated_due = ?, stated_na = ? WHERE sheet_id = ? AND id = ?",
                claim.isStated(), claim.getStatedDue(), claim.isStatedNa(), claim.getSheetId(), claim.getId());
    }

    /** Defers the stored OPEN claim until the date; false when it is no longer OPEN (another user moved it on). */
    public boolean defer(Claim claim, LocalDate until) {
        boolean deferred = jdbc.update("UPDATE claim SET deferred_until = ? WHERE sheet_id = ? AND id = ? AND status = ?",
                Date.valueOf(until), claim.getSheetId(), claim.getId(), ClaimStatus.OPEN.name()) == 1;
        if (deferred) {
            claim.setDeferredUntil(until);
        }
        return deferred;
    }

    /** Reminds the stored OPEN or PENDING claim on {@code today}; false when it is no longer one of those or was
     *  already reminded that day (another user got there first). */
    public boolean remind(Claim claim, LocalDate today) {
        boolean reminded = jdbc.update("UPDATE claim SET reminded_on = ? WHERE sheet_id = ? AND id = ? AND status IN (?, ?)"
                + " AND (reminded_on IS NULL OR reminded_on <> ?)", Date.valueOf(today), claim.getSheetId(), claim.getId(),
                ClaimStatus.OPEN.name(), ClaimStatus.PENDING.name(), Date.valueOf(today)) == 1;
        if (reminded) {
            claim.setRemindedOn(today);
        }
        return reminded;
    }

    /** Re-dates the stored OPEN or PENDING claim, under {@code number}; false when it is no longer one of
     *  those at the date it had (another user changed it first). Its due-by and any statement figure stay. */
    public boolean redate(Claim claim, LocalDate date, String number) {
        boolean redated = jdbc.update("UPDATE claim SET claim_date = ?, number = ? "
                + "WHERE sheet_id = ? AND id = ? AND status IN (?, ?) AND claim_date = ?",
                Date.valueOf(date), number, claim.getSheetId(), claim.getId(), ClaimStatus.OPEN.name(),
                ClaimStatus.PENDING.name(), Date.valueOf(claim.getDate())) == 1;
        if (redated) {
            claim.setDate(date);
            claim.setNumber(number);
        }
        return redated;
    }

    /** Leaves the stored OPEN claim with {@code rest} of its amount, unbound from any statement figure; false
     *  when it is no longer OPEN at the amount it had (another user changed it first). */
    public boolean shrink(Claim claim, BigDecimal rest) {
        boolean shrunk = jdbc.update("UPDATE claim SET amount = ?, stated = FALSE, stated_due = NULL, stated_na = FALSE "
                + "WHERE sheet_id = ? AND id = ? AND status = ? AND amount = ?",
                rest, claim.getSheetId(), claim.getId(), ClaimStatus.OPEN.name(), claim.getAmount()) == 1;
        if (shrunk) {
            claim.setAmount(rest);
            claim.setStated(false);
            claim.setStatedDue(null);
            claim.setStatedNa(false);
        }
        return shrunk;
    }

    /** Adds an OPEN claim split off {@code from}: its date, note and tags, the given number, opened by the user
     *  and due by {@code dueBy}, fixed for {@code terms} business days after its date, listed as its person's newest claim. */
    public Claim addSplit(Claim from, BigDecimal amount, String number, String openedBy, LocalDate dueBy, int terms) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, number, opened_by, due_by, split_from, tags, due_terms) "
                            + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    new String[] { "ID" });
            ps.setString(1, from.getSheetId());
            ps.setLong(2, from.getPersonId());
            ps.setBigDecimal(3, amount);
            ps.setDate(4, Date.valueOf(from.getDate()));
            ps.setString(5, from.getNote());
            ps.setString(6, ClaimStatus.OPEN.name());
            ps.setString(7, number);
            ps.setString(8, openedBy);
            ps.setDate(9, Date.valueOf(dueBy));
            ps.setString(10, from.getNumber());
            ps.setString(11, from.getTags());
            ps.setInt(12, terms);
            return ps;
        }, keys);
        Claim added = new Claim(keys.getKey().longValue(), from.getSheetId(), from.getPersonId(), amount, from.getDate(),
                from.getNote(), ClaimStatus.OPEN, number, null, openedBy, false, null, null, dueBy);
        added.setSplitFrom(from.getNumber());
        added.setTags(from.getTags());
        return added;
    }

    /** Works out again the due-by of every claim on the sheet that is not SETTLED or VOID and is due by
     *  {@code from} or later: the business day the terms it was fixed with after its date, skipping weekends
     *  and the given holidays (see {@link HolidayStore#businessDaysAfter}). */
    public void refixDueBy(String sheetId, LocalDate from, Set<LocalDate> holidays) {
        jdbc.query("SELECT id, claim_date, due_by, due_terms FROM claim WHERE sheet_id = ? AND status NOT IN (?, ?) "
                + "AND due_by >= ? AND due_terms IS NOT NULL ORDER BY id", rs -> {
                    LocalDate dueBy = HolidayStore.businessDaysAfter(holidays, rs.getObject("claim_date", LocalDate.class),
                            rs.getInt("due_terms"));
                    if (!dueBy.equals(rs.getObject("due_by", LocalDate.class))) {
                        jdbc.update("UPDATE claim SET due_by = ? WHERE sheet_id = ? AND id = ?", Date.valueOf(dueBy),
                                sheetId, rs.getLong("id"));
                    }
                }, sheetId, ClaimStatus.SETTLED.name(), ClaimStatus.VOID.name(), Date.valueOf(from));
    }

    /** Raises the stored DRAFT, OPEN or PENDING claim's proofs count by one; false when it is no longer one of
     *  those (another user moved it on). */
    public boolean addProof(Claim claim) {
        boolean added = jdbc.update("UPDATE claim SET proofs = proofs + 1 WHERE sheet_id = ? AND id = ? AND status IN (?, ?, ?)",
                claim.getSheetId(), claim.getId(), ClaimStatus.DRAFT.name(), ClaimStatus.OPEN.name(),
                ClaimStatus.PENDING.name()) == 1;
        if (added) {
            claim.setProofs(jdbc.queryForObject("SELECT proofs FROM claim WHERE sheet_id = ? AND id = ?", Integer.class,
                    claim.getSheetId(), claim.getId()));
        }
        return added;
    }

    /** Moves the stored DRAFT, OPEN or PENDING claim to the person under {@code number} (null for a draft),
     *  unbound from any statement figure and listed as their newest claim; false when it is no longer one of
     *  those under the number it had (another user moved it on). */
    public boolean reassign(Claim claim, long personId, String number) {
        boolean moved = jdbc.update("UPDATE claim SET person_id = ?, number = ?, stated = FALSE, stated_due = NULL, "
                + "stated_na = FALSE, listed = NEXT VALUE FOR claim_listed_seq "
                + "WHERE sheet_id = ? AND id = ? AND status IN (?, ?, ?) AND number IS NOT DISTINCT FROM ?",
                personId, number, claim.getSheetId(), claim.getId(), ClaimStatus.DRAFT.name(), ClaimStatus.OPEN.name(),
                ClaimStatus.PENDING.name(), claim.getNumber()) == 1;
        if (moved) {
            claim.setPersonId(personId);
            claim.setNumber(number);
            claim.setStated(false);
            claim.setStatedDue(null);
            claim.setStatedNa(false);
        }
        return moved;
    }

    /** Moves the stored claim from {@code from} to {@code to}, locking its row until the transaction
     *  ends; false when it is no longer {@code from} (another user moved it first). */
    public boolean move(Claim claim, ClaimStatus from, ClaimStatus to) {
        return jdbc.update("UPDATE claim SET status = ? WHERE sheet_id = ? AND id = ? AND status = ?", to.name(),
                claim.getSheetId(), claim.getId(), from.name()) == 1;
    }

    /** Records the bulk settle batch the claim was settled in. */
    public void markBatch(Claim claim, long batch) {
        jdbc.update("UPDATE claim SET settle_batch = ? WHERE sheet_id = ? AND id = ?", batch, claim.getSheetId(), claim.getId());
        claim.setBatch(batch);
    }

    /** Takes the next bulk settle batch on the sheet: 1, then 2, and so on, locked as {@link #nextNumber(String)} is. */
    public long nextBatch(String sheetId) {
        try {
            jdbc.update("INSERT INTO settle_batch (sheet_id, last_batch) SELECT ?, 0 FROM DUAL "
                    + "WHERE NOT EXISTS (SELECT 1 FROM settle_batch WHERE sheet_id = ?)", sheetId, sheetId);
        } catch (DataAccessException e) {
            // another transaction added the sheet's counter first
        }
        jdbc.update("UPDATE settle_batch SET last_batch = last_batch + 1 WHERE sheet_id = ?", sheetId);
        return jdbc.queryForObject("SELECT last_batch FROM settle_batch WHERE sheet_id = ?", Long.class, sheetId);
    }

    /** Takes the next claim number on the sheet: 1, then 2, and so on. The sheet's counter row stays
     *  locked until the transaction ends, so a number is never given twice, and is not used up if
     *  the transaction rolls back. */
    public long nextNumber(String sheetId) {
        try {
            jdbc.update("INSERT INTO claim_number (sheet_id, last_number) SELECT ?, 0 FROM DUAL "
                    + "WHERE NOT EXISTS (SELECT 1 FROM claim_number WHERE sheet_id = ?)", sheetId, sheetId);
        } catch (DataAccessException e) {
            // another transaction added the sheet's counter first
        }
        jdbc.update("UPDATE claim_number SET last_number = last_number + 1 WHERE sheet_id = ?", sheetId);
        return jdbc.queryForObject("SELECT last_number FROM claim_number WHERE sheet_id = ?", Long.class, sheetId);
    }

    /** Takes the next number in one of the sheet's per-period sequences: 1, then 2, and so on, locked
     *  as {@link #nextNumber(String)} is. */
    public long nextNumber(String sheetId, String sequence) {
        try {
            jdbc.update("INSERT INTO claim_period_number (sheet_id, sequence, last_number) SELECT ?, ?, 0 FROM DUAL "
                    + "WHERE NOT EXISTS (SELECT 1 FROM claim_period_number WHERE sheet_id = ? AND sequence = ?)",
                    sheetId, sequence, sheetId, sequence);
        } catch (DataAccessException e) {
            // another transaction added the sequence's counter first
        }
        jdbc.update("UPDATE claim_period_number SET last_number = last_number + 1 WHERE sheet_id = ? AND sequence = ?",
                sheetId, sequence);
        return jdbc.queryForObject("SELECT last_number FROM claim_period_number WHERE sheet_id = ? AND sequence = ?",
                Long.class, sheetId, sequence);
    }

    /** Moves every claim of {@code fromId} to {@code intoId}, keeping their numbers and dates, each unbound from any
     *  statement figure and listed after the claims {@code intoId} has, in the order they were listed. */
    public void moveAll(String sheetId, long fromId, long intoId) {
        for (Long id : jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY listed",
                Long.class, sheetId, fromId)) {
            jdbc.update("UPDATE claim SET person_id = ?, stated = FALSE, stated_due = NULL, stated_na = FALSE, "
                    + "listed = NEXT VALUE FOR claim_listed_seq WHERE sheet_id = ? AND id = ?", intoId, sheetId, id);
        }
    }

    /** Adds a copy of the claim to the person on the other sheet under {@code number} (null for none), correcting
     *  and split off the numbers given: its amount, date, note, status, frozen settled figure, opener, due-by and
     *  the terms it was fixed with, deferral, proofs, late entry, reminder, tags, void reason and editor, with its
     *  status log and comments, listed as the person's newest claim. Any figure a statement bound, its reference,
     *  lock and bulk settle batch are not carried. The id of the copy. */
    public long copyTo(Claim claim, String toSheet, long toPerson, String number, String corrects, String splitFrom) {
        Integer terms = jdbc.queryForObject("SELECT due_terms FROM claim WHERE sheet_id = ? AND id = ?", Integer.class,
                claim.getSheetId(), claim.getId());
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, number, settled_due, opened_by, "
                            + "corrects, due_by, due_terms, deferred_until, proofs, split_from, late_entry, reminded_on, tags, "
                            + "void_reason, edited_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    new String[] { "ID" });
            ps.setString(1, toSheet);
            ps.setLong(2, toPerson);
            ps.setBigDecimal(3, claim.getAmount());
            ps.setDate(4, Date.valueOf(claim.getDate()));
            ps.setString(5, claim.getNote());
            ps.setString(6, claim.getStatus().name());
            ps.setString(7, number);
            ps.setBigDecimal(8, claim.getSettledDue());
            ps.setString(9, claim.getOpenedBy());
            ps.setString(10, corrects);
            ps.setDate(11, Date.valueOf(claim.getDueBy()));
            ps.setObject(12, terms, java.sql.Types.INTEGER);
            ps.setDate(13, claim.getDeferredUntil() == null ? null : Date.valueOf(claim.getDeferredUntil()));
            ps.setInt(14, claim.getProofs());
            ps.setString(15, splitFrom);
            ps.setBoolean(16, claim.isLateEntry());
            ps.setDate(17, claim.getRemindedOn() == null ? null : Date.valueOf(claim.getRemindedOn()));
            ps.setString(18, claim.getTags());
            ps.setString(19, claim.getVoidReason());
            ps.setString(20, claim.getEditedBy());
            return ps;
        }, keys);
        long id = keys.getKey().longValue();
        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, log_date, due) "
                + "SELECT ?, ?, status, by_user, log_date, due FROM claim_log WHERE sheet_id = ? AND claim_id = ? ORDER BY id",
                toSheet, id, claim.getSheetId(), claim.getId());
        jdbc.update("INSERT INTO claim_comment (sheet_id, claim_id, by_user, written_on, text) "
                + "SELECT ?, ?, by_user, written_on, text FROM claim_comment WHERE sheet_id = ? AND claim_id = ? ORDER BY id",
                toSheet, id, claim.getSheetId(), claim.getId());
        return id;
    }

    /** Drops every claim of the person, with their status logs and comments. */
    public void removeAll(String sheetId, long personId) {
        String mine = "SELECT id FROM claim WHERE sheet_id = ? AND person_id = ?";
        jdbc.update("DELETE FROM claim_log WHERE sheet_id = ? AND claim_id IN (" + mine + ")", sheetId, sheetId, personId);
        jdbc.update("DELETE FROM claim_comment WHERE sheet_id = ? AND claim_id IN (" + mine + ")", sheetId, sheetId, personId);
        jdbc.update("DELETE FROM claim WHERE sheet_id = ? AND person_id = ?", sheetId, personId);
    }
}
package net.officefloor.hq.app.person;

import java.sql.PreparedStatement;
import java.util.ArrayList;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;
import net.officefloor.hq.app.history.History;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The people kept per sheet, in list order (by their position: a new person goes to the end, a move swaps
 *  two neighbours), each with their dated grades. */
@Repository
public class PersonStore {

    private final JdbcTemplate jdbc;

    public PersonStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The people's grades on the sheet (only the one person when {@code personId} is given), by person. */
    private Map<Long, NavigableMap<LocalDate, String>> grades(String sheetId, Long personId, String table) {
        Map<Long, NavigableMap<LocalDate, String>> grades = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, grade FROM " + table + " WHERE sheet_id = ?"
                + (personId == null ? "" : " AND person_id = " + personId), rs -> {
                    grades.computeIfAbsent(rs.getLong("person_id"), k -> new TreeMap<>())
                            .put(rs.getObject("from_date", LocalDate.class), rs.getString("grade"));
                }, sheetId);
        return grades;
    }

    /** The people's holds on the sheet (only the one person's when {@code personId} is given), by person, oldest first. */
    private Map<Long, List<Hold>> holds(String sheetId, Long personId, String table) {
        Map<Long, List<Hold>> holds = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, to_date FROM " + table + " WHERE sheet_id = ?"
                + (personId == null ? "" : " AND person_id = " + personId) + " ORDER BY id", rs -> {
                    holds.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(new Hold(
                            rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class)));
                }, sheetId);
        return holds;
    }

    /** The people's aliases on the sheet (only the one person's when {@code personId} is given), by person,
     *  sorted as names are compared. */
    private Map<Long, List<String>> aliases(String sheetId, Long personId, String table) {
        Map<Long, List<String>> aliases = new HashMap<>();
        jdbc.query("SELECT person_id, alias FROM " + table + " WHERE sheet_id = ?"
                + (personId == null ? "" : " AND person_id = " + personId) + " ORDER BY LOWER(alias), alias", rs -> {
                    aliases.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(rs.getString("alias"));
                }, sheetId);
        return aliases;
    }

    /** The people's past retirements on the sheet (only the one person's when {@code personId} is given), by
     *  person, oldest first. */
    private Map<Long, List<PastRetirement>> pastRetirements(String sheetId, Long personId) {
        Map<Long, List<PastRetirement>> past = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, to_date FROM person_retirement WHERE sheet_id = ?"
                + (personId == null ? "" : " AND person_id = " + personId) + " ORDER BY id", rs -> {
                    past.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(new PastRetirement(
                            rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class)));
                }, sheetId);
        return past;
    }

    private List<Person> query(String sheetId, Long personId, String sql, Object... args) {
        return queryFrom(sheetId, personId, "person_grade", "person_hold", "person_alias", sql, args);
    }

    private List<Person> queryFrom(String sheetId, Long personId, String gradeTable, String holdTable,
            String aliasTable, String sql, Object... args) {
        Map<Long, NavigableMap<LocalDate, String>> grades = grades(sheetId, personId, gradeTable);
        Map<Long, List<Hold>> holds = holds(sheetId, personId, holdTable);
        Map<Long, List<String>> aliases = aliases(sheetId, personId, aliasTable);
        Map<Long, List<PastRetirement>> past = pastRetirements(sheetId, personId);
        RowMapper<Person> row = (rs, i) -> {
            Person p = new Person(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"),
                    grades.getOrDefault(rs.getLong("id"), new TreeMap<>()), rs.getLong("version"),
                    rs.getObject("retired_from", LocalDate.class), holds.getOrDefault(rs.getLong("id"), List.of()));
            p.setTerms(rs.getObject("terms", Integer.class));
            p.setContact(rs.getString("contact"));
            p.setOrigin(rs.getString("origin"));
            p.getAliases().addAll(aliases.getOrDefault(rs.getLong("id"), List.of()));
            p.getPastRetirements().addAll(past.getOrDefault(rs.getLong("id"), List.of()));
            return p;
        };
        return jdbc.query(sql, row, args);
    }

    public List<Person> list(String sheetId) {
        return query(sheetId, null, "SELECT * FROM person WHERE sheet_id = ? ORDER BY list_position, id", sheetId);
    }

    /** The people on the sheet as they stood at the end of the date, with their grades and holds then (see
     *  {@link History}), in list order then. */
    public List<Person> listAsOf(String sheetId, LocalDate date) {
        return queryFrom(sheetId, null, History.asOf("person_grade", "person_id, from_date", date),
                History.asOf("person_hold", "id", date), History.asOf("person_alias", "id", date),
                "SELECT * FROM " + History.asOf("person", "id", date) + " WHERE sheet_id = ? ORDER BY list_position, id", sheetId);
    }

    public Person find(String sheetId, long id) {
        List<Person> found = query(sheetId, id, "SELECT * FROM person WHERE sheet_id = ? AND id = ?", sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person as they stood at the end of the date, with their grades and holds then (see {@link History});
     *  null when they were not on the sheet then. */
    public Person findAsOf(String sheetId, long id, LocalDate date) {
        List<Person> found = queryFrom(sheetId, id, History.asOf("person_grade", "person_id, from_date", date),
                History.asOf("person_hold", "id", date), History.asOf("person_alias", "id", date),
                "SELECT * FROM " + History.asOf("person", "id", date) + " WHERE sheet_id = ? AND id = ?", sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person on the sheet with this name or alias, ignoring case and the spaces around it; null when none. */
    public Person findByName(String sheetId, String name) {
        List<Person> found = query(sheetId, null, "SELECT * FROM person WHERE sheet_id = ? AND (name_key = LOWER(?)"
                + " OR id IN (SELECT person_id FROM person_alias WHERE sheet_id = ? AND alias_key = LOWER(?)))",
                sheetId, name.trim(), sheetId, name.trim());
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether another person on the sheet (not {@code exceptId}) has this name, or anyone on the sheet has it
     *  as an alias, ignoring case. */
    public boolean nameTaken(String sheetId, String name, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(?) AND id <> ?",
                Integer.class, sheetId, name.trim(), exceptId == null ? -1L : exceptId);
        return (n != null && n > 0) || aliasTaken(sheetId, name);
    }

    /** Whether anyone on any of the sheets has this name or alias, ignoring case and the spaces around it. */
    public boolean usedOn(List<String> sheetIds, String name) {
        for (String sheetId : sheetIds) {
            if (nameTaken(sheetId, name, null)) {
                return true;
            }
        }
        return false;
    }

    /** The names and aliases used on any of the sheets, lower-cased. */
    public java.util.Set<String> namesOn(List<String> sheetIds) {
        java.util.Set<String> names = new java.util.HashSet<>();
        for (String sheetId : sheetIds) {
            names.addAll(jdbc.queryForList("SELECT name_key FROM person WHERE sheet_id = ?", String.class, sheetId));
            names.addAll(jdbc.queryForList("SELECT alias_key FROM person_alias WHERE sheet_id = ?", String.class,
                    sheetId));
        }
        return names;
    }

    /** Whether the person's name or any of their aliases is among the names (lower-cased). */
    public static boolean clashes(Person person, java.util.Set<String> names) {
        if (names.contains(person.getName().trim().toLowerCase(java.util.Locale.ROOT))) {
            return true;
        }
        return person.getAliases().stream().anyMatch(a -> names.contains(a.trim().toLowerCase(java.util.Locale.ROOT)));
    }

    /** Whether anyone on the sheet has this alias, ignoring case and the spaces around it. */
    public boolean aliasTaken(String sheetId, String alias) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM person_alias WHERE sheet_id = ? AND alias_key = LOWER(?)",
                Integer.class, sheetId, alias.trim());
        return n != null && n > 0;
    }

    /** Adds the alias (trimmed) to the person's aliases. An edit of their name or grade leaves them as they are. */
    public void addAlias(Person person, String alias) {
        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) VALUES (?, ?, ?)", person.getSheetId(),
                person.getId(), alias.trim());
        person.getAliases().add(alias.trim());
        person.getAliases().sort(java.util.Comparator.comparing((String a) -> a.toLowerCase(java.util.Locale.ROOT))
                .thenComparing(java.util.Comparator.naturalOrder()));
    }

    /** Adds the person with their first grade, which applies from the beginning of time, and no terms of their own. */
    public Person add(String sheetId, String name, String grade) {
        return add(sheetId, name, grade, null);
    }

    /** Adds the person with their first grade, which applies from the beginning of time, and their own
     *  terms (null for none). */
    public Person add(String sheetId, String name, String grade, Integer terms) {
        return add(sheetId, name, grade, terms, null);
    }

    /** Whether another person on the sheet (not {@code exceptId}) has this contact (trimmed, lower-cased). */
    public boolean contactTaken(String sheetId, String contact, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND contact = ? AND id <> ?",
                Integer.class, sheetId, contact, exceptId == null ? -1L : exceptId);
        return n != null && n > 0;
    }

    /** Adds the person with their first grade, which applies from the beginning of time, their own
     *  terms (null for none) and their contact (null for none). */
    public Person add(String sheetId, String name, String grade, Integer terms, String contact) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO person (sheet_id, name, terms, contact, list_position) VALUES (?, ?, ?, ?, (SELECT"
                    + " COALESCE(MAX(list_position), 0) + 1 FROM person WHERE sheet_id = ?))", new String[] { "ID" });
            ps.setString(1, sheetId);
            ps.setString(2, name);
            ps.setObject(3, terms, java.sql.Types.INTEGER);
            ps.setString(4, contact);
            ps.setString(5, sheetId);
            return ps;
        }, keys);
        long id = keys.getKey().longValue();
        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, ?, ?)", sheetId,
                id, Person.START, grade);
        Person person = new Person(id, sheetId, name, new TreeMap<>(Map.of(Person.START, grade)), 0);
        person.setTerms(terms);
        person.setContact(contact);
        return person;
    }

    /**
     * Stores the person over the version it was loaded at, moving the version on; false (nothing
     * stored) when someone else has stored another version since. The grade the edit records (if any)
     * is kept with the ones already recorded, replacing one from the same date.
     */
    public boolean save(Person person) {
        int n = jdbc.update(
                "UPDATE person SET name = ?, terms = ?, contact = ?, version = version + 1 WHERE sheet_id = ? AND id = ? AND version = ?",
                person.getName(), person.getTerms(), person.getContact(), person.getSheetId(), person.getId(), person.getVersion());
        if (n == 1) {
            person.setVersion(person.getVersion() + 1);
            LocalDate from = person.getRecordFrom();
            if (from != null) {
                jdbc.update("MERGE INTO person_grade (sheet_id, person_id, from_date, grade) KEY (person_id, from_date)"
                        + " VALUES (?, ?, ?, ?)", person.getSheetId(), person.getId(), from, person.getGrades().get(from));
            }
        }
        return n == 1;
    }

    /**
     * Swaps the person with their neighbour in the list (the one above when {@code up}, else the one below);
     * answers the person's new position in the list, counting from 1, or 0 (nothing stored) when there is no
     * neighbour that way: the top cannot move up, nor the bottom down. An edit of them leaves it as it is.
     */
    public int move(Person person, boolean up) {
        List<long[]> order = jdbc.query("SELECT id, list_position FROM person WHERE sheet_id = ? ORDER BY list_position, id"
                + " FOR UPDATE", (rs, i) -> new long[] { rs.getLong("id"), rs.getLong("list_position") },
                person.getSheetId());
        int at = -1;
        for (int i = 0; i < order.size(); i++) {
            if (order.get(i)[0] == person.getId()) {
                at = i;
            }
        }
        int to = up ? at - 1 : at + 1;
        if (at < 0 || to < 0 || to >= order.size()) {
            return 0;
        }
        long[] mine = order.get(at);
        long[] theirs = order.get(to);
        if (mine[1] == theirs[1]) {
            // tied positions (never made by this store): number them apart first, so the swap moves them
            renumber(person.getSheetId(), order);
            return move(person, up);
        }
        jdbc.update("UPDATE person SET list_position = ? WHERE sheet_id = ? AND id = ?", theirs[1], person.getSheetId(),
                mine[0]);
        jdbc.update("UPDATE person SET list_position = ? WHERE sheet_id = ? AND id = ?", mine[1], person.getSheetId(),
                theirs[0]);
        return to + 1;
    }

    /** Gives the people positions 1, 2, ... in their present order. */
    private void renumber(String sheetId, List<long[]> order) {
        for (int i = 0; i < order.size(); i++) {
            jdbc.update("UPDATE person SET list_position = ? WHERE sheet_id = ? AND id = ?", i + 1, sheetId, order.get(i)[0]);
        }
    }

    /** Retires the person from the date. An edit of their name or grade leaves it as it is. */
    public void retire(Person person, LocalDate from) {
        jdbc.update("UPDATE person SET retired_from = ? WHERE sheet_id = ? AND id = ?", from, person.getSheetId(),
                person.getId());
        person.setRetiredFrom(from);
    }

    /** Unretires the person on the date, keeping their retirement as a past one, from its date to this one. */
    public void unretire(Person person, LocalDate on) {
        jdbc.update("INSERT INTO person_retirement (sheet_id, person_id, from_date, to_date) VALUES (?, ?, ?, ?)",
                person.getSheetId(), person.getId(), person.getRetiredFrom(), on);
        jdbc.update("UPDATE person SET retired_from = NULL WHERE sheet_id = ? AND id = ?", person.getSheetId(),
                person.getId());
        person.getPastRetirements().add(new PastRetirement(person.getRetiredFrom(), on));
        person.setRetiredFrom(null);
    }

    /** Adds a hold to the person's holds. An edit of their name or grade leaves them as they are. */
    public void hold(Person person, Hold hold) {
        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date) VALUES (?, ?, ?, ?)",
                person.getSheetId(), person.getId(), hold.from(), hold.to());
        person.addHold(hold);
    }

    /** Adds a copy of the person to the other sheet: their name, every grade with its from-date, their terms,
     *  contact and aliases, noting this sheet as the one they came from. Their holds, statements and watchers
     *  are not carried. */
    public Person copyTo(Person person, String toSheet) {
        Person copy = add(toSheet, person.getName(), person.gradeOn(Person.START), person.getTerms(), person.getContact());
        person.getGrades().forEach((from, grade) -> {
            if (!from.equals(Person.START)) {
                jdbc.update("INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, ?, ?)",
                        toSheet, copy.getId(), from, grade);
            }
        });
        for (String alias : person.getAliases()) {
            addAlias(copy, alias);
        }
        jdbc.update("UPDATE person SET origin = ? WHERE sheet_id = ? AND id = ?", person.getSheetId(), toSheet,
                copy.getId());
        return find(toSheet, copy.getId());
    }

    /** Drops the person from their sheet with their grades, holds, aliases, statements and watchers. Their claims,
     *  patrons and pool memberships are dropped before this (see ClaimStore, PatronStore and PoolStore). */
    public void remove(Person person) {
        String sheetId = person.getSheetId();
        jdbc.update("DELETE FROM person_alias WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM person_hold WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM person_retirement WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM statement WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM watch WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
    }

    /** Makes the person's name and aliases aliases of {@code into}, then drops the person with their grades,
     *  holds, statements and watchers (their contact goes with them). Their claims, patrons and pool
     *  memberships are moved before this (see ClaimStore, PatronStore and PoolStore). */
    public void mergeInto(Person person, Person into) {
        String sheetId = person.getSheetId();
        jdbc.update("UPDATE person_alias SET person_id = ? WHERE sheet_id = ? AND person_id = ?", into.getId(), sheetId,
                person.getId());
        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, person.getId());
        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) VALUES (?, ?, ?)", sheetId, into.getId(),
                person.getName());
        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM person_hold WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM person_retirement WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM statement WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM watch WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
    }
}

