    /** The sum of people's figures, leaving out the single highest and the single lowest when three or more
     *  people have one. */
    private static BigDecimal trimmed(List<BigDecimal> figures) {
        List<BigDecimal> sorted = new ArrayList<>(figures);
        sorted.sort(null);
        if (sorted.size() >= 3) {
            sorted = sorted.subList(1, sorted.size() - 1);
        }
        return sorted.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** Each person's due-total of their claims due by a date in from..to (inclusive) that count by the status they
     *  had at the end of {@code to} (see {@link #countsAt}), by person id in the order they were added: the
     *  sum of their figures as shown now, skipping n/a, as the screen shows a person's due-total for a
     *  period. A period's due-total is the sum of these. */
    public Map<Long, BigDecimal> dueBetweenByPerson(String sheetId, LocalDate from, LocalDate to) {
        LocalDate today = sheets.today(sheetId);
        List<Claim> all = claims.list(sheetId);
        Lateness lateness = lateness(sheetId, today, all);
        Map<Long, ClaimStatus> atEnd = log.statusesAt(sheetId, to);
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        for (Person person : people.list(sheetId)) {
            BigDecimal total = BigDecimal.ZERO.setScale(2);
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId()
                        || !countsAt(claim, atEnd.get(claim.getId()), person, today)
                        || claim.getDueBy().isBefore(from) || claim.getDueBy().isAfter(to)) {
                    continue;
                }
                BigDecimal figure = lateness.due(claim, rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()));
                if (figure != null) {
                    total = total.add(figure);
                }
            }
            totals.put(person.getId(), total);
        }
        return totals;
    }

    /** Records how the sheet's figures moved since {@code before}, the change made by {@code user}. */
    public void record(String sheetId, String user, Rollup before) {
        Rollup after = snapshot(sheetId);
        String who = " sheet=" + sheetId + " by=" + user;
        after.people().forEach((id, now) -> {
            if (!now.sameAs(before.people().get(id))) {
                audit.record("ROLLUP" + who + " person=" + now.name() + " claimed=" + now.claimed() + " due-total="
                        + now.dueTotal() + " overdue-total=" + now.overdueTotal());
            }
        });
        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())
                || !after.overdueTotal().equals(before.overdueTotal())) {
            audit.record("TOTALS" + who + " claimed-total=" + after.claimedTotal() + " due-total=" + after.dueTotal()
                    + " overdue-total=" + after.overdueTotal());
        }
    }

    /** What the sheet's late charge follows on the date, for these claims (see {@link Lateness}). */
    private Lateness lateness(String sheetId, LocalDate today, List<Claim> all) {
        Map<Long, Person> byId = new HashMap<>();
        people.list(sheetId).forEach(person -> byId.put(person.getId(), person));
        return new Lateness(settings.latePcts(sheetId), settings.floors(sheetId), today,
                new Rounding(policyDate(sheetId), all), Lateness.graced(settings.graces(sheetId), byId::get));
    }

    /** The date the sheet's rounding turns on: the policy date set, else the sheet's today. */
    private LocalDate policyDate(String sheetId) {
        LocalDate policy = settings.policyDate(sheetId);
        return policy != null ? policy : sheets.today(sheetId);
    }

    /** Only OPEN, PENDING and SETTLED claims count, and an OPEN or PENDING claim dated within one of its
     *  person's holds, or of a person whose retirement date the sheet's today has reached, does not, unless a
     *  statement bound it; nor does an OPEN claim deferred on the sheet's today. */
    public static boolean counts(Claim claim, Person person, LocalDate today) {
        return claim.getStatus() == ClaimStatus.SETTLED
                || (claim.getStatus().isOpen() && !claim.isDeferredOn(today)
                        && (claim.isStated() || !(person.heldOn(claim.getDate()) || person.retiredOn(today))));
    }

    /** Whether the claim counts by {@code status}, the status it had at a period's end (null when it
     *  was added after it): OPEN, PENDING or SETTLED then; and, as the live rules say, an OPEN claim
     *  deferred on the sheet's today does not, nor one open then and still open now dated within a hold
     *  of its person or of a person retired on the sheet's today, unless a statement bound it. */
    static boolean countsAt(Claim claim, ClaimStatus status, Person person, LocalDate today) {
        return status == ClaimStatus.SETTLED
                || (status != null && status.isOpen() && !claim.isDeferredOn(today)
                        && (claim.isStated() || !claim.getStatus().isOpen()
                                || !(person.heldOn(claim.getDate()) || person.retiredOn(today))));
    }

    private static String shown(BigDecimal value) {
        return value.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.plugin.variable.Val;

/** Records a transfer on both sheets: PERSON_TRANSFERRED sheet=<this> by=<user> name=<name> to=<other>, then
 *  PERSON_TRANSFERRED sheet=<other> by=<user> name=<name> from=<this>, each followed by how it moved that
 *  sheet's figures. */
public class AuditPersonTransferred {
    public void audit(@Val TransferRequest request, @Val Person person, @Val Transferred transferred,
            @Val Rollup before, Audit audit, RollupService rollups) {
        String from = person.getSheetId();
        String to = transferred.to();
        audit.record("PERSON_TRANSFERRED sheet=" + from + " by=" + request.user() + " name=" + person.getName()
                + " to=" + to);
        rollups.record(from, request.user(), before);
        audit.record("PERSON_TRANSFERRED sheet=" + to + " by=" + request.user() + " name=" + person.getName()
                + " from=" + from);
        rollups.record(to, request.user(), transferred.toBefore());
    }
}
# POST /api/sheets/{sheetId}/people/{personId}/transfer — transfer a person to another sheet by id (body:
# {to, user}). Only a steward transfers. The person arrives on the other sheet with every grade (and its
# from-date), their terms, contact and aliases, and their claims with their status, dates, notes, frozen
# figures, logs and comments; each claim that had a number takes the other sheet's next number, in the order
# the claims were opened (by the sheet's today when each was opened, then the order they were added). Figures a
# statement bound are lost, the statement count starts at 0 and references are not carried. They leave this
# sheet entirely (patron links, pool memberships, holds, statements and watches dropped). Refused (400),
# storing nothing, when the user is not a steward, the person is not on the sheet or is retired, the other
# sheet is missing, this sheet or archived, or already has their name, an alias of theirs or their contact.
# A stored transfer is recorded as PERSON_TRANSFERRED on both sheets, each followed by its rollup lines.
validate:
  class: net.officefloor.hq.app.person.ValidateTransfer
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: transfer
transfer:
  class: net.officefloor.hq.app.person.TransferPerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.AuditPersonTransferred
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithTransferred
  govern: [ transaction ]

